Para = {}  # parameter dict

def parameter_add(name,element):
    try:
        Para[str(name)] = element    
    except:
        print(f"parameter_add({element}) Fail.")
        return False

def parameter_get(name):    
    try:
        e = Para[str(name)]
    except:
        e = None
    return e


_tls = threading.local()

def get_file_name(n=None):
    """Thread-local file_name setter/getter.
    - get_file_name("xxx.log") -> set
    - get_file_name() -> get
    """
    if n is not None:
        _tls.file_name = n
        return n
    return getattr(_tls, "file_name", None)

def _current_log_file(fallback="Report/_unknown.log"):
    return get_file_name() or fallback


# 定義一個裝飾器，用於自動重試
def retry(max_retries=2, delay=2):
    # file_name = parameter_get("file_name")
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            log_file = _current_log_file()
            print(f"                                                                                           [TIME]",file = open(log_file, '+a'))
            print(f"             In {func.__name__} {os.path.abspath(func.__code__.co_filename)}:{func.__code__.co_firstlineno}",file = open(log_file, '+a'))
            start_time = time.time()      
            tmp = None
            try:
                driver_tmp = args[0]
            except:
                pass            
            for attempt in range(max_retries):                
                try:
                    # print(f"Executing {func.__name__}, Attempt: {attempt + 1}")                
                    # return func(*args, **kwargs)
                    tmp = func(*args, **kwargs)
                    
                    total_time = time.time() - start_time
                    print(f'                                                                                           [TIME {int(total_time/60/60)}:{int(total_time/60%60)}:{int(total_time%60)}]   {str(datetime.datetime.now())}',file = open(log_file, '+a'))
                    
                    return tmp
                except Exception as e:

                    try:
                        e = str(e).split("Stacktrace")[0]
                    except:
                        pass

                    print(f"\nError in {func.__name__}: {e}",file = open(log_file, '+a'))
                    PrintException(log_file)
                    if attempt < max_retries - 1:
                        # Attempt to recover renderer before retrying:
                        # navigate to about:blank so Chrome can release renderer
                        # resources before the next driver.get() call.
                        try:
                            driver_tmp.execute_script("window.stop();")
                        except Exception:
                            pass
                        try:
                            driver_tmp.get("about:blank")
                        except Exception:
                            pass
                        time.sleep(delay)
                    else:
                        print(f"{func.__name__} failed after {max_retries} attempts. Skipping...",file = open(log_file, '+a'))                      
                        print(f"======================================================================================",file = open(log_file, '+a'))
                        
                        total_time = time.time() - start_time
                        print(f'                                                                                           [TIME {int(total_time/60/60)}:{int(total_time/60%60)}:{int(total_time%60)}]   {str(datetime.datetime.now())}',file = open(log_file, '+a'))

                        try:
                            # driver.save_screenshot(f"D:/tmp.png")                    
                            driver_tmp.save_screenshot(f'Report/{str(datetime.datetime.now()).split(":")[0]}{str(datetime.datetime.now()).split(":")[1]}.{str(datetime.datetime.now()).split(":")[2][:5]}_{func.__name__}_screenshot.png')
                        except:
                            pass   


                        return None                
                    print(f"-------------------------------------- Retry -----------------------------------------",file = open(log_file, '+a'))    
       
       
        return wrapper
    return decorator   



