def Profile_Mode_Page_Test(driver,output_path,prof_name,file_name):
    if_error = False
    time.sleep(3)
    if(e_pro.Profile_Table_List_Edit_Name(driver,prof_name) == False):
        print(f"             [{output_path}] not found '{prof_name}' in the first or last page",file = open(file_name, '+a'))
        if_error = True
    else:
        # Edit  -- use explicit wait instead of bare find_element to avoid 300s renderer timeout
        try:
            elem = WebDriverWait(driver, 30).until(
                EC.visibility_of_element_located((By.XPATH, '//*[@id="create_profile_background"]/div[1]/div'))
            )
            text = elem.text
        except Exception:
            text = ""
        if(text != 'Edit Profile'):
            print(f"             [{output_path}] click Edit detect: {text} != 'Edit Profile' Test Fail",file = open(file_name, '+a'))
            if_error = True 
        else:
            print(f"             [{output_path}] click Edit detect: {text} = 'Edit Profile' Test Pass",file = open(file_name, '+a'))
        # Create
        time.sleep(3)
        e_pro.New_Profile(driver)
        # Use WebDriverWait instead of time.sleep(10) + find_element to avoid renderer timeout
        try:
            elem = WebDriverWait(driver, 30).until(
                EC.visibility_of_element_located((By.XPATH, '//*[@id="create_profile_background"]/div[1]/div'))
            )
            text = elem.text
        except Exception:
            text = ""
        if(text != 'Create Profile'):
            print(f"             [{output_path}] click New  detect: {text} != 'Create Profile' Test Fail",file = open(file_name, '+a'))
            if_error = True 
        else:
            print(f"             [{output_path}] click New  detect: {text} = 'Create Profile' Test Pass",file = open(file_name, '+a'))    
    return if_error

def EMS_Login_Password_Security_Test(url,username,password, ems_url, ems_password,file_name):
   
    print(f"EMS Web Test")           
    print(f"Only detect if there is 'value' attribute...")           
    driver = webdriver.Chrome()
    driver.get(url)

    driver.find_element(By.ID,"name").clear()
    driver.find_element(By.ID,"name").send_keys(username)
    driver.find_element(By.ID,"passwd").clear()
    driver.find_element(By.ID,"passwd").send_keys(ems_password) 
    print(f"After send keys...")           
    try:
        ele = driver.find_element(By.ID, "passwd").get_attribute("value")        
        print(f"Found 'value' attribute, value:{ele}, Test Fail")
    except:
        print(f"Test Pass")           
    
    driver.find_element(By.ID,"signin").click()     
    print(f"After click sign in...")           
    try:
        ele = driver.find_element(By.ID, "passwd").get_attribute("value")        
        print(f"Found 'value' attribute, value:{ele}, Test Fail")
    except:
        print(f"Test Pass")
    print()

    driver.quit()

