def EMS_Provision_Config_path(driver,url):
    driver.switch_to.default_content()
    time.sleep(1) 
    Wait_Block(driver)
    driver.find_element(By.LINK_TEXT, "Provision").click()
    # time.sleep(3)
    time.sleep(1)
    Wait_Block(driver)
    driver.find_element(By.LINK_TEXT, "Configuration").click()
    time.sleep(1)
    Wait_Block(driver)
    # driver.find_element(By.LINK_TEXT, "Configuration").click()
    # time.sleep(1)
    # Wait_Block(driver)

    # input ip
    url_ip = url.split("/")[2]    
    driver.find_element(By.ID, "map_key_filter").clear()
    driver.find_element(By.ID, "map_key_filter").send_keys(url_ip)
    time.sleep(1)
    # click filter
    driver.find_element(By.ID, "map_key_searsh").click()
    time.sleep(1)
    # click EMS
    # driver.find_element(By.CLASS_NAME, "icon.expand-icon.oi.oi-plus").click()  # click '+'  
    # click Cecily                     
    # driver.find_element(By.CLASS_NAME, "icon.expand-icon.oi.oi-plus").click()  # click '+'

    try:
        driver.find_element(By.CLASS_NAME, "icon.expand-icon.oi.oi-plus").click()  # click '+'
    except:
        pass

    driver.find_element(By.CLASS_NAME, "list-group-item.node-navMenuTree.node-selected").click()  # click '[]'
    time.sleep(2)
    
    # click IES 192.168.xxx.xxx
    # print(f"test after 192.168.: {url_ip[8:]}")
    # driver.find_element(By.XPATH, f'//*[@title="IES6217_{url_ip[8:]}({url_ip})"]').click()
    try:
        driver.find_element('xpath',f"//*[contains(text(),'{url_ip}')]").click()
    except:
        # [Apply device]    
        def Input(driver, text,id):
            driver.find_element(By.ID,id).send_keys(Keys.CONTROL + 'a')
            driver.find_element(By.ID,id).send_keys(text)
        def Click(driver,mytype,ele):
            WebDriverWait(driver, timeout=10).until(EC.visibility_of_element_located((mytype,ele))) 
            WebDriverWait(driver, timeout=10).until(EC.element_to_be_clickable((mytype,ele))).click()  
        # print(f"             [step3 Apply device] - - - - - - - - - - - - - - -",file = open(file_name, '+a'))
        Click(driver,By.LINK_TEXT,"System")             
        Click(driver,By.LINK_TEXT,"Security")             
        Click(driver,By.LINK_TEXT,"Map Management")             
        Click(driver,By.LINK_TEXT,"EMS")             
        Click(driver,By.ID,"i_action_create_device")          # Add btn    
        Input(driver,f"{module.variable_module.device_name}_{url_ip[-3:]}","deviceName")
        Input(driver,url_ip,"deviceIP")
        Input(driver,module.variable_module.login_username,"userName")
        Input(driver,module.variable_module.login_password,"dev_password")
        Input(driver,module.variable_module.set_community,"setCommunity")
        Input(driver,module.variable_module.get_community,"getCommunity")
        Click(driver,By.XPATH,"//input[@value='Apply']")             
        # print(f"             [EMS - System - Security - Map Management] Apply Device msg:{e_mod.alert_accept_text(driver)}",file = open(file_name, '+a'))
        # print(f"             [wait] wait 3 min",file = open(file_name, '+a'))

        time.sleep(60)
        e_mod.OK(driver)

        # (again)
        driver.find_element(By.LINK_TEXT, "Provision").click()
        time.sleep(3)
        Wait_Block(driver)
        driver.find_element(By.LINK_TEXT, "Configuration").click()
        time.sleep(1)
        Wait_Block(driver)
        driver.find_element(By.LINK_TEXT, "Configuration").click()
        time.sleep(1)
        Wait_Block(driver)
        # input ip
        url_ip = url.split("/")[2]    
        driver.find_element(By.ID, "map_key_filter").clear()
        driver.find_element(By.ID, "map_key_filter").send_keys(url_ip)
        time.sleep(1)
        # click filter
        driver.find_element(By.ID, "map_key_searsh").click()
        time.sleep(1)
        
        driver.find_element(By.CLASS_NAME, "list-group-item.node-navMenuTree.node-selected").click()  # click '[]'
        driver.find_element('xpath',f"//*[contains(text(),'{url_ip}')]").click()

    driver.switch_to.frame(0)
    # the device config menu inside the frame loads asynchronously (seen blank after a fixed 2 s on EMS 128.100);
    # wait for it so callers' LINK_TEXT clicks (ACL / Multicast / System ...) do not race it. Best-effort.
    try:
        WebDriverWait(driver, 60).until(lambda d: any(
            d.find_elements(By.LINK_TEXT, t) for t in ("ACL", "Multicast", "System", "VLAN", "Switch")))
    except Exception:
        pass


    
    




