def Retry_Test_func(func,file_name,test_limit):
    if_pass = False
    count = 0
    while(if_pass == False):
        # func()
        # if_pass = True 
        
        try:
            # func()
            func
            if_pass = True         
        except Exception as e:
            
            try:
                e = str(e).split('\n')[0]
            except:
                e = '(fail get info)'
            print(f"             Action fail",file = open(file_name, '+a'))                               
            print(f"             VSCode: {e}",file = open(file_name, '+a'))                               
            count = count + 1
            if(count == test_limit):
                print("======================================================================================",file = open(file_name, '+a'))
                break
                return
            else:   
                print(f" - - - - - - - - - try again - - - - - - - - - ",file = open(file_name, '+a')) 

