def EMS_ACL_DHCP_Remote_Backup1(driver,url,slot,username,password, ems_url, ems_password,file_name):

    if_EMS_error = False
    if_FW_error = False
    if_apply_error = False
    if_download_error = False

    # --------------------- EMS web start ---------------------
    # EMS - ACL - DHCP Remote Backup
    
    driver.get(ems_url)
    time.sleep(3)
    mod.Login_EMS(driver,username,ems_password)
    time.sleep(3)
    EMS_Provision_Config_path(driver,url)
    time.sleep(2)    
    driver.find_element(By.LINK_TEXT,"ACL").click()          
    time.sleep(1)
    driver.find_element(By.LINK_TEXT,"DHCP Remote Backup").click()
