    # Manual Download Test
    try:
        e_acl.DHCP_Remote_Backup_Slot(driver,slot)
        print(f"             [ACL - DHCP Remote Backup] EMS Slot Select Pass",file = open(file_name, '+a'))
    except:
        print(f"             [ACL - DHCP Remote Backup] EMS Slot Select Fail",file = open(file_name, '+a'))
        if_EMS_error = True
        if_download_error = True
    e_acl.DHCP_Remote_Backup_Manual_Download(driver)
    msg = alert_accept_text(driver)
    if(if_msg_not_success(msg)):
        print(f"             [ACL - DHCP Remote Backup] EMS msg:{msg}  Manual Download Fail",file = open(file_name, '+a'))
        if_EMS_error = True
        if_download_error = True
    else:
        print(f"             [ACL - DHCP Remote Backup] EMS msg:{msg}  Manual Download Pass",file = open(file_name, '+a'))
    # Check Download Status
    if_find = False
    for i in range(driver.find_elements(By.CLASS_NAME,"zy_tr.acl_remotebackup_table_row2").__len__()):
        web_slot = driver.find_elements(By.XPATH,'//*[@class="zy_tr acl_remotebackup_table_row2"]/div[@class="zy_td acl_remotebackup_table_slot"]')[i].text
        if web_slot == slot:
            status = driver.find_elements(By.XPATH,'//*[@class="zy_tr acl_remotebackup_table_row2"]/div[@class="zy_td acl_remotebackup_table_ds"]')[i].text.strip()
            if status == "---":
                print(f"             [ACL - DHCP Remote Backup] EMS Manual Download Status : {status}==--- Test Fail",file = open(file_name, '+a'))
                if_EMS_error = True
                if_download_error = True
            else:
                print(f"             [ACL - DHCP Remote Backup] EMS Manual Download Status : {status}!=--- Test Pass",file = open(file_name, '+a'))
            if_find = True
            break
    if not if_find:
        print(f"             [ACL - DHCP Remote Backup] EMS Not Found Slot {slot} Status Manual Download Status Test Fail",file = open(file_name, '+a'))
        if_EMS_error = True
        if_download_error = True
    # --------------------- EMS web end -----------------------
    # --------------------- FW web check start ----------------
    if_FW_error = False
    driver.get(url) 
    time.sleep(3)
    mod.Login(driver,username,password) 
    time.sleep(3)
    # ACL > DHCP > DHCP Remote Backup
    mod.Switch_Default(driver)
    mod.Page_Switch(driver,"ACL")
    mod.SubPage_Switch(driver,"DHCP")
    mod.Switch_Frame(driver)
    mod.SubPage_Switch(driver,"DHCP Remote Backup")
    time.sleep(1)                    
    acl.Slot_Select(driver,slot)     
    acl.Load(driver)  
    time.sleep(1)                    
    # tmp = driver.find_element(By.NAME,"rpdhcprmtbk_ftpip").get_attribute('value')
    # if tmp.strip() != "10.10.10.10":
    #     print(f"             [ACL - DHCP - DHCP Remote Backup] FW FTP : {tmp}!=10.10.10.10 Test Fail",file = open(file_name, '+a'))
    #     if_FW_error = True
    #     if_apply_error = True
    # else:
    #     print(f"             [ACL - DHCP - DHCP Remote Backup] FW FTP : 10.10.10.10 Test Pass",file = open(file_name, '+a'))
    # tmp = driver.find_element(By.NAME,"rpdhcprmtbk_account").get_attribute('value')
    # if tmp.strip() != "1234657890123456789012345678901":
    #     print(f"             [ACL - DHCP - DHCP Remote Backup] FW Account : {tmp}!=1234657890123456789012345678901 Test Fail",file = open(file_name, '+a'))
    #     if_FW_error = True
    #     if_apply_error = True
    # else:
    #     print(f"             [ACL - DHCP - DHCP Remote Backup] FW Account : 1234657890123456789012345678901 Test Pass",file = open(file_name, '+a'))
    # tmp = driver.find_element(By.NAME,"rpdhcprmtbk_password").get_attribute('value')
    # if tmp.strip() != "1234657890123456789012345678901":
    #     print(f"             [ACL - DHCP - DHCP Remote Backup] FW Password : {tmp}!=1234657890123456789012345678901 Test Fail",file = open(file_name, '+a'))
    #     if_FW_error = True
    #     if_apply_error = True
    # else:
    #     print(f"             [ACL - DHCP - DHCP Remote Backup] FW Password : 1234657890123456789012345678901 Test Pass",file = open(file_name, '+a'))
    # tmp = driver.find_element(By.NAME,"rpdhcprmtbk_filepath").get_attribute('value')
    # if tmp.strip() != "1234657890123456789012345678901":
    #     print(f"             [ACL - DHCP - DHCP Remote Backup] FW Filepath : {tmp}!=1234657890123456789012345678901 Test Fail",file = open(file_name, '+a'))
    #     if_FW_error = True
    #     if_apply_error = True
    # else:
    #     print(f"             [ACL - DHCP - DHCP Remote Backup] FW Filepath : 1234657890123456789012345678901 Test Pass",file = open(file_name, '+a'))
    if_find = False
    for i in range(driver.find_elements(By.CLASS_NAME,"td-table-content.Slot").__len__()):
        if driver.find_elements(By.CLASS_NAME,"td-table-content.Slot")[i].text == slot:
            status = driver.find_elements(By.CLASS_NAME,"td-table-content.LastDownloadStatus")[i].text
            if status.strip() == "---":
                print(f"             [ACL - DHCP - DHCP Remote Backup] FW Download Status : {status}==--- Test Fail",file = open(file_name, '+a'))
                if_FW_error = True
            else:
                print(f"             [ACL - DHCP - DHCP Remote Backup] FW Download Status : {status}!=--- Test Pass",file = open(file_name, '+a'))
            if_find = True
            break
    if not if_find:
        print(f"             [ACL - DHCP - DHCP Remote Backup] FW Not Found Slot {slot} Download Status Test Fail",file = open(file_name, '+a'))
        if_download_error = True
        if_FW_error = True
        # --------------------- FW web check end ------------------

    # EMS Result
    if(if_EMS_error == True):
        print(f"             [ACL - DHCP Remote Backup] EMS web check fail",file = open(file_name, '+a'))
    else:
        print(f"             [ACL - DHCP Remote Backup] EMS web check pass",file = open(file_name, '+a')) 

    # FW Result
    if(if_FW_error == True):
        print(f"             [ACL - DHCP Remote Backup] FW web check fail",file = open(file_name, '+a'))
    else:
        print(f"             [ACL - DHCP Remote Backup] FW web check pass",file = open(file_name, '+a')) 

    # if not if_apply_error:
    #     print(f"  [EMS1-6105][ACL - DHCP Remote Backup Apply] Result Pass",file = open(file_name, '+a'))
    # else:
    #     print(f"  [EMS1-6105][ACL - DHCP Remote Backup Apply] Result Fail",file = open(file_name, '+a'))
    if not if_download_error:
        print(f"  [EMS1-6106][ACL - DHCP Remote Backup Manual download] Result Pass",file = open(file_name, '+a'))
    else:
        print(f"  [EMS1-6106][ACL - DHCP Remote Backup Manual download] Result Fail",file = open(file_name, '+a'))
    
    # Final Result    
    output_id = '0000'
    if((if_EMS_error == False) and (if_FW_error == False)):
        print(f"  [EMS1-{output_id}][ACL - DHCP Remote Backup] Result Pass",file = open(file_name, '+a'))
    else:
        print(f"  [EMS1-{output_id}][ACL - DHCP Remote Backup] Result Fail",file = open(file_name, '+a'))
    # print("======================================================================================",file = open(file_name, '+a'))


