def EMS_8021x_IES_Not_Support(driver,url,username,ems_url,ems_password,file_name,link_text,cases):
    # IES52xx has no 802.1x General Setup / Radius Server / User Profile pages (only 802.1x Port Setting per card).
    # Returns True when the device is IES52xx and the not-support check was done instead of the normal test.
    driver.get(url)
    time.sleep(2)
    if "NeoX" in driver.title:
        return False
    print(f"             {NO_SUPPORT} IES52xx: ACL > {link_text} page should not exist",file = open(file_name, '+a'))
    driver.get(ems_url)
    time.sleep(3)
    mod.Login_EMS(driver,username,ems_password)
    time.sleep(3)
    EMS_Provision_Config_path(driver,url)
    time.sleep(2)
    driver.find_element(By.LINK_TEXT,"ACL").click()
    time.sleep(2)
    found = [e.text for e in driver.find_elements(By.LINK_TEXT, link_text) if e.is_displayed()]
    result = 'Fail' if found else 'Pass'
    print(f"             [ACL - {link_text}] EMS page {'found' if found else 'not found'} Test {result}",file = open(file_name, '+a'))
    for case in cases:
        print(f"  {case} Result {result}",file = open(file_name, '+a'))
    return True

@retry()
def EMS_ACL_8021x_General_Setup_Test(driver,url,username,password, ems_url, ems_password,file_name):
    print(f"EMS - ACL - 802.1x - General Setup Test\n",file = open(file_name, '+a'))
    print(f"  [EMS1-7057][ACL - 802.1x - General Setup Save]",file = open(file_name, '+a'))
    if EMS_8021x_IES_Not_Support(driver,url,username,ems_url,ems_password,file_name,"802.1x",["[EMS1-7057][ACL - 802.1x - General Setup Save]"]):
        return
    if_EMS_error = False
    if_FW_error = False        
    
    keys = ["User Profile", "Radius"]
    for key in keys:
        driver.get(ems_url)
        time.sleep(3)
        mod.Login_EMS(driver,username,ems_password)
        time.sleep(3)
        EMS_Provision_Config_path(driver,url)
        time.sleep(2)   
        driver.find_element(By.LINK_TEXT,"ACL").click()          
        time.sleep(2)   
        driver.find_element(By.LINK_TEXT,"802.1x").click()          
        # driver.find_element(By.ID,"acl_802_1x").click()     
        # driver.find_element('xpath',f"//*[contains(text(),'802.1x')]").click()     
        time.sleep(3)

        # EMS Set
        e_acl.x802_1x_General_Setup_Method(driver,key)
        e_acl.x802_1x_General_Setup_Apply(driver)
        msg = alert_accept_text(driver)
        if(if_msg_not_success(msg)):
            print(f"             [ACL - 802.1x - General Setup] EMS msg:{msg}  Apply Fail",file = open(file_name, '+a'))
            if_EMS_error = True
        else:
            print(f"             [ACL - 802.1x - General Setup] EMS msg:{msg}  Apply Pass",file = open(file_name, '+a'))

        # EMS Check
        time.sleep(2)   
        # driver.find_element(By.LINK_TEXT,"ACL").click()          
        time.sleep(2)   
        driver.find_element(By.LINK_TEXT,"802.1x").click()          
        # driver.find_element(By.ID,"acl_802_1x").click()          
        # driver.find_element('xpath',f"//*[contains(text(),'802.1x')]").click()     
        time.sleep(2)   
        tmp = Select(driver.find_element(By.ID,f"acl_8021x_general_authentication_method_select")).first_selected_option.text
        if(tmp != key):
            print(f"             [ACL - 802.1x - General Setup] EMS Authentication Method {tmp}!={key} Test Fail",file = open(file_name, '+a'))
            if_EMS_error = True 
        else:
            print(f"             [ACL - 802.1x - General Setup] EMS Authentication Method  {key} Test Pass",file = open(file_name, '+a'))

        # - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
        # FW Check
        driver.get(url) 
        time.sleep(3)
        mod.Login(driver,username,password) 
        time.sleep(3)
        mod.Switch_Default(driver)
        mod.Page_Switch(driver,"ACL")
        mod.SubPage_Switch(driver,"802.1x")
        mod.Switch_Frame(driver)
        time.sleep(2)  
        tmp = Select(driver.find_element(By.NAME,f"rpDot1x_authMethod")).first_selected_option.text
        key = key.replace(" ","")
        if(tmp.lower() != key.lower()):
            print(f"             [ACL - 802.1x - General Setup] FW Authentication Method {tmp.lower()}!={key.lower()} Test Fail",file = open(file_name, '+a'))
            if_FW_error = True 
        else:
            print(f"             [ACL - 802.1x - General Setup] FW Authentication Method  {key.lower()} Test Pass",file = open(file_name, '+a'))
    if((if_EMS_error == False) and (if_FW_error == False)):
        print(f"  [EMS1-7057][ACL - 802.1x - General Setup Save] Result Pass",file = open(file_name, '+a'))
    else:
        print(f"  [EMS1-7057][ACL - 802.1x - General Setup Save] Result Fail",file = open(file_name, '+a'))

