@retry()
def EMS_ACL_8021x_Port_Setting_Test(driver,url,list_element,username,password, ems_url, ems_password,file_name):
    print(f"EMS - ACL - 802.1x - Port Setting Test\n",file = open(file_name, '+a'))
    print(f"  [EMS1-7058][ACL - 802.1x - Port Setting - Save]",file = open(file_name, '+a'))        
    slot = list_element.split(",")[1]
    port = list_element.split(",")[2]
    cardtype = list_element.split(",")[3]
    print(f"             ({cardtype} {slot}-{port})",file = open(file_name, '+a'))


    print_list = []
    print_list.append('[EMS1-7058][ACL - 802.1x - Port Setting - Save]')
  

    driver.get(url)
    time.sleep(2)
    if "NeoX" in driver.title:
        match list_element[:1]:            
            case "1": # NXA
                EMS_ACL_8021x_Port_Setting_Test_1(driver,url,slot,port,username,password, ems_url, ems_password,file_name)                 
            case "2": # NXP    /OLC3416B/OLC3708/OLC3816
                EMS_ACL_8021x_Port_Setting_Test_nosup(driver,url,slot,port,username,password, ems_url, ems_password,file_name)                  
            case "3": # NXP    /OLC3416/
                EMS_ACL_8021x_Port_Setting_Test_nosup(driver,url,slot,port,username,password, ems_url, ems_password,file_name)                  
            case "4": # NXC
                EMS_ACL_8021x_Port_Setting_Test_nosup(driver,url,slot,port,username,password, ems_url, ems_password,file_name)                              
            case _:                
                print(f"             No Action (not in any case)",file = open(file_name, '+a')) 
    else:
        driver.get(ems_url)
        time.sleep(3)
        mod.Login_EMS(driver,username,ems_password)
        time.sleep(3)
        EMS_Provision_Config_path(driver,url)
        time.sleep(2)   
        driver.find_element(By.LINK_TEXT,"ACL").click()          
        try:
            time.sleep(2)   
            driver.find_element(By.LINK_TEXT,"802.1x").click() 
            print(f"             [ACL - 802.1x - Port Setting] EMS Page Found Test Fail",file = open(file_name, '+a'))
            print(f"  [EMS1-7058][ACL - 802.1x - Port Setting - Save] Result Fail",file = open(file_name, '+a'))        
        except:
            print(f"             [ACL - 802.1x - Port Setting] EMS Page Not Found Test Pass",file = open(file_name, '+a'))
            print(f"  [EMS1-7058][ACL - 802.1x - Port Setting - Save] Result Pass",file = open(file_name, '+a'))        



    print("======================================================================================",file = open(file_name, '+a'))

