    if(driver.find_element(By.XPATH, f"/html/body/form/div[6]/div/div[{int(port)+19}]/div[3]/select/option[1]").is_selected() != True):
        print(f"             [ACL - 802.1x - Port Setting] FW Port{port} Control (Auto) Test Fail",file = open(file_name, '+a'))
        if_FW_error = True
    else:
        print(f"             [ACL - 802.1x - Port Setting] FW Port{port} Control (Auto) Test Pass",file = open(file_name, '+a'))
    if(driver.find_element(By.XPATH, f"/html/body/form/div[6]/div/div[{int(port)+19}]/div[4]/select/option[1]").is_selected() != True):
        print(f"             [ACL - 802.1x - Port Setting] FW Port{port} Server Index (1) Test Fail",file = open(file_name, '+a'))
        if_FW_error = True
    else:
        print(f"             [ACL - 802.1x - Port Setting] FW Port{port} Server Index (1) Test Pass",file = open(file_name, '+a'))
    if(driver.find_elements(By.NAME, "rpdot1x_portcfg_chk_authonce")[int(port)-1].is_selected() != True):
        print(f"             [ACL - 802.1x - Port Setting] FW Port{port} Auth Once (True) Test Fail",file = open(file_name, '+a'))
        if_FW_error = True
    else:
        print(f"             [ACL - 802.1x - Port Setting] FW Port{port} Auth Once (True) Test Pass",file = open(file_name, '+a'))
    tmp = driver.find_elements(By.NAME, "rpdot1x_portcfg_period")[int(port)-1].get_attribute("value")
    if(tmp != "60"):
        print(f"             [ACL - 802.1x - Port Setting] FW Port{port} Reauth Period ({tmp}!=60) Test Fail",file = open(file_name, '+a'))
        if_FW_error = True
    else:
        print(f"             [ACL - 802.1x - Port Setting] FW Port{port} Reauth Period (60) Test Pass",file = open(file_name, '+a'))
    tmp = driver.find_elements(By.NAME, "rpdot1x_portcfg_ipt_circuid_id")[int(port)-1].get_attribute("value")
    if(tmp != "60"):
        print(f"             [ACL - 802.1x - Port Setting] FW Port{port} Circuit ID ({tmp}!=60) Test Fail",file = open(file_name, '+a'))
        if_FW_error = True   
    else: 
        print(f"             [ACL - 802.1x - Port Setting] FW Port{port} Circuit ID (60) Test Pass",file = open(file_name, '+a'))
    
    if((if_EMS_error == False) and (if_FW_error == False)):
        print(f"  [EMS1-7058][ACL - 802.1x - Port Setting - Save] Result Pass",file = open(file_name, '+a'))        
    else:
        print(f"  [EMS1-7058][ACL - 802.1x - Port Setting - Save] Result Fail",file = open(file_name, '+a'))        
   


