def EMS_ACL_MAC_Count_1(driver,url,output_id,slot,port,username,password, ems_url, ems_password,file_name, cardtype):
    if_EMS_error = False
    if_FW_error = False
    if_LimitNum_apply_error = False
    if_vlan_new_error = False
    if_delete_error = False
    
    if ("OLC3416" in cardtype): 
        maxMacCount = 1023
        minMacCount = 0
    else: 
        maxMacCount = 256
        minMacCount = 1

    # --------------------- EMS web start ---------------------
    # EMS - ACL - MAC Count
    driver.get(ems_url)
    time.sleep(2)    
    e_mod.Login_EMS(driver,username,ems_password)
    time.sleep(2)    
    EMS_Provision_Config_path(driver,url)
    time.sleep(2)    
    driver.find_element(By.LINK_TEXT, "ACL").click()          
    time.sleep(1)
    driver.find_element(By.LINK_TEXT, "MAC Count").click()
    time.sleep(1)
    try:
        e_acl.Select_Slot(driver,slot)
        e_acl.Select_Port(driver,port)
    except:
        print(f"             [ACL - MAC Count] EMS Slot Port Select fail",file = open(file_name, '+a'))
        if_EMS_error = True
        if_LimitNum_apply_error = True
        if_vlan_new_error = True
        

    if(if_EMS_error == False):

        # MAC Count Limit Test _ invalid/valid input apply check & value check
        # test_keys = ["0","257","@"]
        test_keys = [f"{minMacCount-1}",f"{maxMacCount+1}","@"]
        for i in test_keys:
            try:
                e_acl.MAC_Count_Limit_Input(driver,i)
                e_acl.Save(driver)
                # wait until?
                time.sleep(1.5)  
                alert_accept(driver) # "enter"            
            except:
                alert_accept(driver)      

            # try:
            #     driver.find_element(By.ID, "popupClose").click()          #need_add modify?
            #     print(f"             [ACL - MAC Count] EMS Limited Number invalid input:{i} apply Test pass*",file = open(file_name, '+a'))
            # except:
            #     print(f"             [ACL - MAC Count] EMS Limited Number invalid input:{i} apply Test fail*",file = open(file_name, '+a'))
            #     if_EMS_error = True

            # check output != input
            EMS_Reload_Page_Configuration(driver,url)
            driver.find_element(By.LINK_TEXT, "ACL").click()        
            time.sleep(1)
            driver.find_element(By.LINK_TEXT, "MAC Count").click()
            time.sleep(1)   
            e_acl.Select_Slot(driver,slot)
            e_acl.Select_Port(driver,port)                     
            time.sleep(1)   
            value = driver.find_element(By.ID, "acl_maccount_limit_num").get_attribute("value")
            if(value == i):
                print(f"             [ACL - MAC Count] EMS Limited Number invalid input:{value} = {i} Test fail",file = open(file_name, '+a'))
                if_EMS_error = True
                if_LimitNum_apply_error = True
            else:
                print(f"             [ACL - MAC Count] EMS Limited Number invalid input:{value} != {i} Test pass",file = open(file_name, '+a'))
            

        # test_keys = ["1","256"]
        test_keys = [f"{minMacCount}",f"{maxMacCount}"]
        for i in test_keys:
            e_acl.MAC_Count_Limit_Input(driver,i)
            e_acl.Save(driver)
            time.sleep(1)  
            alert_accept(driver) # "enter"
            # try:
            #     driver.find_element(By.ID, "popupClose").click()         #need_add modify?
            #     print(f"             [ACL - MAC Count] EMS Limited Number valid input:{i} apply Test fail*",file = open(file_name, '+a'))
            #     if_EMS_error = True
            # except:
            #     print(f"             [ACL - MAC Count] EMS Limited Number valid input:{i} apply Test pass*",file = open(file_name, '+a'))
            
            # check output = input            
            EMS_Reload_Page_Configuration(driver,url)
            driver.find_element(By.LINK_TEXT, "ACL").click()        
            time.sleep(1)
            driver.find_element(By.LINK_TEXT, "MAC Count").click()
            time.sleep(1)   
            e_acl.Select_Slot(driver,slot)
            e_acl.Select_Port(driver,port)                     
            time.sleep(1)   
            value = driver.find_element(By.ID, "acl_maccount_limit_num").get_attribute("value")
            if(value != i):
                print(f"             [ACL - MAC Count] EMS Limited Number valid input:{value} != {i} Test fail",file = open(file_name, '+a'))
                if_EMS_error = True
                if_LimitNum_apply_error = True
            else:
                print(f"             [ACL - MAC Count] EMS Limited Number valid input:{value} = {i} Test pass",file = open(file_name, '+a'))

        # New Vlan, Limit
        # test_keys = ["0","257","@"]
        test_keys = [f"{minMacCount-1}",f"{maxMacCount+1}","@"]
        for i in test_keys:
            e_acl.MAC_Count_Limit_New(driver) 
            e_acl.MAC_Count_Limit_New_Vlan(driver,"4094") 
            e_acl.MAC_Count_Limit_New_Limit(driver,i) 
            e_mod.OK(driver)
            msg = alert_accept_text(driver)
            print(f"             [ACL - MAC Count] EMS Vlan New invalid input:{i} apply msg:{msg}",file = open(file_name, '+a'))
            if(SUCCESS_TEXT in msg):
                print(f"             [ACL - MAC Count] EMS Vlan New invalid input:{i} apply Test fail",file = open(file_name, '+a'))
                if_EMS_error = True
                if_vlan_new_error = True
            else:
                print(f"             [ACL - MAC Count] EMS Vlan New invalid input:{i} apply Test pass",file = open(file_name, '+a'))
            try:
                e_pro.Close(driver)
            except:
                pass
                
        # test_keys = ["1","256"]
        test_keys = [f"{minMacCount}",f"{maxMacCount}"]
        for i in test_keys:
            e_acl.MAC_Count_Limit_New(driver) 
            e_acl.MAC_Count_Limit_New_Vlan(driver,"4094") 
            e_acl.MAC_Count_Limit_New_Limit(driver,i) 
            e_mod.OK(driver)
            time.sleep(1)  
            alert_accept(driver) # "enter" 
            try:
                driver.find_element(By.ID, "popupClose").click()
                print(f"             [ACL - MAC Count] EMS Vlan New valid input:{i} apply Test fail",file = open(file_name, '+a'))
                if_EMS_error = True
                if_vlan_new_error = True
            except:
                print(f"             [ACL - MAC Count] EMS Vlan New valid input:{i} apply Test pass",file = open(file_name, '+a'))
            try:
                e_pro.Close(driver)
            except:
                pass

        # Table Switch Page Test
        print(f"             [ACL - MAC Count] (Table Switch Page Test)",file = open(file_name, '+a'))
        if_table_error = False
        for i in range(1,8):
            e_acl.MAC_Count_Limit_New(driver) 
            time.sleep(2) 
            e_acl.MAC_Count_Limit_New_Vlan(driver,4000+i) 
            e_acl.MAC_Count_Limit_New_Limit(driver,'1') 
            e_mod.OK(driver)
            msg = alert_accept_text(driver)
            if if_msg_not_success(msg):
                print(f"             [ACL - MAC Count] EMS Vlan:{4000+i} Limit:1 Apply msg:'{msg}' Test Fail",file = open(file_name, '+a'))
                if_EMS_error = True
                if_table_error = True
            else:
                print(f"             [ACL - MAC Count] EMS Vlan:{4000+i} Limit:1 Apply msg:'{msg}' Test Pass",file = open(file_name, '+a'))
            e_mod.Close2(driver)   
        i = 8
        try:
            e_acl.MAC_Count_Limit_New(driver)
            time.sleep(2) 
            e_acl.MAC_Count_Limit_New_Vlan(driver,4000+i) 
            e_acl.MAC_Count_Limit_New_Limit(driver,'1') 
            e_mod.OK(driver)
            msg = alert_accept_text(driver)
            if if_msg_not_success(msg):
                print(f"             [ACL - MAC Count] EMS Vlan:{4000+i} Limit:1 Apply msg:'{msg}' Test Pass",file = open(file_name, '+a'))
            else:
                print(f"             [ACL - MAC Count] EMS Vlan:{4000+i} Limit:1 Apply msg:'{msg}' Test Fail",file = open(file_name, '+a'))
                if_EMS_error = True
                if_table_error = True
            e_mod.Close2(driver)  
        except:
            print(f"             [ACL - MAC Count] EMS Vlan:{4000+i} Limit:1 New Fail Test Pass",file = open(file_name, '+a'))

        # Click NextPage PrevPage
        try:
            e_mod.NextPage_Click(driver)
            print(f"             [ACL - MAC Count] EMS clicked NextPage btn",file = open(file_name, '+a'))
            table_row = driver.find_elements(By.CLASS_NAME, "zy_tr.acl_maccount_table_row").__len__()
            if table_row != 0:
                print(f"             [ACL - MAC Count] EMS Table Row Num {table_row}!=0 Table Switch Page After NextPage Test Pass",file = open(file_name, '+a'))
            else:
                print(f"             [ACL - MAC Count] EMS Table Row Num {table_row}=0 Table Switch Page After NextPage Test Fail",file = open(file_name, '+a'))
                if_table_error = True
            e_mod.PrevPage_Click(driver)
            print(f"             [ACL - MAC Count] EMS clicked PrevPage btn",file = open(file_name, '+a'))
            table_row = driver.find_elements(By.CLASS_NAME, "zy_tr.acl_maccount_table_row").__len__()
            if table_row != 0:
                print(f"             [ACL - MAC Count] EMS Table Row Num {table_row}!=0 Table Switch Page After PrevPage Test Pass",file = open(file_name, '+a'))
            else:
                print(f"             [ACL - MAC Count] EMS Table Row Num {table_row}=0 Table Switch Page After PrevPage Test Fail",file = open(file_name, '+a'))
                if_table_error = True            
        except:
            print(f"             [ACL - MAC Count] EMS Table Switch Page Test Fail",file = open(file_name, '+a'))
            if_table_error = True
        if not if_table_error:
            print(f"  [EMS1-6121][ACL - MAC Count - VLAN Limit - Table Page Switch] Result Pass",file = open(file_name, '+a'))
        else:
            print(f"  [EMS1-6121][ACL - MAC Count - VLAN Limit - Table Page Switch] Result Fail",file = open(file_name, '+a'))

        # check value
        if_find = False
        count = 0
        for index in range(driver.find_elements(By.CLASS_NAME, "zy_tr.acl_maccount_table_row").__len__()):
            if(driver.find_elements(By.CLASS_NAME, "zy_td.acl_maccount_table_vid")[index].get_attribute("textContent") == "4094"):
                if(driver.find_elements(By.CLASS_NAME, "zy_td.acl_maccount_table_limit")[index].text == f"{maxMacCount}"):
                    if_find = True                                                       
                    print(f"             [ACL - MAC Count] EMS Vlan:4094 Limit:{maxMacCount} New input on table Test pass",file = open(file_name, '+a'))
                count = count + 1                                       
        if(if_find == False):
            print(f"             [ACL - MAC Count] EMS Vlan:4094 Limit:{maxMacCount} New input Not Found on table Test fail",file = open(file_name, '+a'))                    
            if_EMS_error = True
            if_vlan_new_error = True
        if(count > 1):
            print(f"             [ACL - MAC Count] EMS Vlan New input one identical Vlan Test fail",file = open(file_name, '+a'))                    
            if_EMS_error = True
            if_vlan_new_error = True
        else:
            print(f"             [ACL - MAC Count] EMS Vlan New input one identical Vlan Test pass",file = open(file_name, '+a'))                                
        # --------------------- EMS web end -----------------------
        # --------------------- FW web check start ----------------
        # ACL > MAC Count 
        driver.get(url) 
        time.sleep(3)
        mod.Login(driver,username,password) 
        time.sleep(3)    
        mod.Switch_Default(driver)
        mod.Page_Switch(driver,"ACL")
        time.sleep(1)    
        driver.find_element(By.LINK_TEXT, "MAC Count").click() 
        mod.Switch_Frame(driver)
        time.sleep(1) 
        # select slot 
        driver.find_elements(By.NAME, "rpdsl_rdoSlt")[int(slot)-1].click()
        # select port
        driver.find_elements(By.NAME, "rpdsl_rdoSlt")[int(port)-1].click()
        time.sleep(1)
        # Check Limited Number of Learned MAC Address
        t = driver.find_element(By.NAME,"rpmacCount_sltMacLimit").get_attribute("value")
        if(t != f"{maxMacCount}"):
            print(f"             [ACL - MAC Count] FW Limited Number {t}!={maxMacCount} Test Fail",file = open(file_name, '+a'))
            if_FW_error = True
            if_LimitNum_apply_error = True
        else:
            print(f"             [ACL - MAC Count] FW Limited Number {maxMacCount} Test Pass",file = open(file_name, '+a'))
        # Check Vlan
        if_find = False                
        for index in range(driver.find_elements(By.CLASS_NAME, "tablelist").__len__()):
            if(driver.find_elements(By.NAME, "rpmacCount_perVlanVlan")[index].get_attribute("textContent") == "4094"):
                if(driver.find_elements(By.NAME, "rpmacCount_perVlanLimit")[index].text == f"{maxMacCount}"):
                    if_find = True                                                       
                    print(f"             [ACL - MAC Count] FW Vlan:4094 Limit:{maxMacCount} New input on table Test pass",file = open(file_name, '+a'))
                    break
        if(if_find == False):
            print(f"             [ACL - MAC Count] FW Vlan:4094 Limit:{maxMacCount} New input Not Found on table Test fail",file = open(file_name, '+a'))
            if_FW_error = True
            if_vlan_new_error = True
        # --------------------- FW web check end ------------------
        if if_LimitNum_apply_error:
            print(f"  [EMS1-6119][ACL - MAC Count - Limited Number - Apply] Result Fail",file = open(file_name, '+a'))
        else:
            print(f"  [EMS1-6119][ACL - MAC Count - Limited Number - Apply] Result Pass",file = open(file_name, '+a'))
        if if_vlan_new_error:
            print(f"  [EMS1-6120][ACL - MAC Count - VLAN Limit - New] Result Fail",file = open(file_name, '+a'))
        else:
            print(f"  [EMS1-6120][ACL - MAC Count - VLAN Limit - New] Result Pass",file = open(file_name, '+a'))


