def EMS_ACL_Packet_Filter_1(driver,url,slot,port,output_id,username,password, ems_url, ems_password,file_name):
    if_EMS_error = False
    if_FW_error = False

    # --------------------- EMS web start ---------------------
    # EMS - ACL - Packet Filter
    
    # EMS website > login
    driver.get(ems_url)
    time.sleep(5)
    mod.Login_EMS(driver,username,ems_password)
    time.sleep(5)
    EMS_Provision_Config_path(driver,url)
    time.sleep(2)    
    driver.find_element(By.LINK_TEXT, "ACL").click()          
    time.sleep(1)
    driver.find_element(By.LINK_TEXT, "Packet Filter").click()
    time.sleep(3)    
    try:
        e_acl.Select_Slot(driver,slot)
        e_acl.Select_Port(driver,port)
    except:
        print(f"             [ACL - Packet Filter] EMS Slot Port select fail",file = open(file_name, '+a')) 
        if_EMS_error = True        
    if(if_EMS_error == False):
        
        e_acl.Packet_Filter_Type(driver,"Custom Reject")
        e_acl.Packet_Filter_PPPoE_Reject(driver,"Enable")
        e_acl.Packet_Filter_IP_Reject(driver,"Enable")
        e_acl.Packet_Filter_ARP_Reject(driver,"Enable")
        e_acl.Packet_Filter_NetBIOS_Reject(driver,"Enable")
        e_acl.Packet_Filter_DHCP_Reject(driver,"Enable")
        e_acl.Packet_Filter_EAPOL_Reject(driver,"Enable")
        e_acl.Packet_Filter_IGMP_Reject(driver,"Enable")
        e_acl.Save(driver)
        time.sleep(1)
        alert_accept(driver) # "enter"

        # check 
        EMS_Reload_Page_Configuration(driver,url)
        driver.find_element(By.LINK_TEXT, "ACL").click()        
        time.sleep(1)
        driver.find_element(By.LINK_TEXT, "Packet Filter").click()
        time.sleep(1)   
        e_acl.Select_Slot(driver,slot)
        e_acl.Select_Port(driver,port)    
        if(driver.find_element(By.XPATH, '//*[@id="acl_packet_filter_filtertype_select"]/option[3]').is_selected() == False):
            print(f"             [ACL - Packet Filter] EMS Packet Fillter Type : Custom Reject fail",file = open(file_name, '+a'))
            if_EMS_error = True
        else:
            print(f"             [ACL - Packet Filter] EMS Packet Fillter Type : Custom Reject pass",file = open(file_name, '+a'))
        if(driver.find_element(By.XPATH, '//*[@id="acl_packet_filter_pppoe_select"]/option[1]').is_selected() == False):
            print(f"             [ACL - Packet Filter] EMS PPPoE Reject : Enable fail",file = open(file_name, '+a'))
            if_EMS_error = True
        else:
            print(f"             [ACL - Packet Filter] EMS PPPoE Reject : Enable pass",file = open(file_name, '+a'))
        if(driver.find_element(By.XPATH, '//*[@id="acl_packet_filter_ip_select"]/option[1]').is_selected() == False):
            print(f"             [ACL - Packet Filter] EMS IP Reject : Enable fail",file = open(file_name, '+a'))
            if_EMS_error = True
        else:
            print(f"             [ACL - Packet Filter] EMS IP Reject : Enable pass",file = open(file_name, '+a'))
        if(driver.find_element(By.XPATH, '//*[@id="acl_packet_filter_arp_select"]/option[1]').is_selected() == False):
            print(f"             [ACL - Packet Filter] EMS ARP Reject : Enable fail",file = open(file_name, '+a'))
            if_EMS_error = True
        else:
            print(f"             [ACL - Packet Filter] EMS ARP Reject : Enable pass",file = open(file_name, '+a'))
        if(driver.find_element(By.XPATH, '//*[@id="acl_packet_filter_netbios_select"]/option[1]').is_selected() == False):
            print(f"             [ACL - Packet Filter] EMS NetBIOS Reject : Enable fail",file = open(file_name, '+a'))
            if_EMS_error = True
        else:
            print(f"             [ACL - Packet Filter] EMS NetBIOS Reject : Enable pass",file = open(file_name, '+a'))
        if(driver.find_element(By.XPATH, '//*[@id="acl_packet_filter_dhcp_select"]/option[1]').is_selected() == False):
            print(f"             [ACL - Packet Filter] EMS DHCP Reject : Enable fail",file = open(file_name, '+a'))
            if_EMS_error = True
        else:
            print(f"             [ACL - Packet Filter] EMS DHCP Reject : Enable pass",file = open(file_name, '+a'))
        if(driver.find_element(By.XPATH, '//*[@id="acl_packet_filter_eapol_select"]/option[1]').is_selected() == False):
            print(f"             [ACL - Packet Filter] EMS EAPOL Reject : Enable fail",file = open(file_name, '+a'))
            if_EMS_error = True
        else:
            print(f"             [ACL - Packet Filter] EMS EAPOL Reject : Enable pass",file = open(file_name, '+a'))
        if(driver.find_element(By.XPATH, '//*[@id="acl_packet_filter_igmp_select"]/option[1]').is_selected() == False):
            print(f"             [ACL - Packet Filter] EMS IGMP Reject : Enable fail",file = open(file_name, '+a'))
            if_EMS_error = True
        else:
            print(f"             [ACL - Packet Filter] EMS IGMP Reject : Enable pass",file = open(file_name, '+a'))
        # --------------------- EMS web end -----------------------
                
        # --------------------- FW web check start ----------------
        # ACL > Packet Filter
        driver.get(url) 
        time.sleep(3)
        mod.Login(driver,username,password) 
        time.sleep(3)    
        mod.Switch_Default(driver)
        mod.Page_Switch(driver,"ACL")
        time.sleep(1)            
        driver.find_element(By.LINK_TEXT, "Packet Filter").click()         
        mod.Switch_Frame(driver)
        time.sleep(1) 
        # slot select
        driver.find_elements(By.NAME, "Pkfiltertableid")[int(slot)-1].click()
        # Packet Filter 檢驗
        if(driver.find_element(By.XPATH, f"//form[@id='rppkfilter_Form']/div[4]/div[{int(port)+19}]/div[2]/select/option[3]").is_selected() != True):
            print("             [ACL - Packet Filter] FW Type Test Fail",file = open(file_name, '+a'))
            if_FW_error = True
        if(driver.find_elements(By.NAME, f"rppkfilterREJECT_PPPoE")[int(port)].is_selected() != True):
            print("             [ACL - Packet Filter] FW PPPoE Test Fail",file = open(file_name, '+a'))
            if_FW_error = True
        if(driver.find_elements(By.NAME, f"rppkfilterREJECT_IP")[int(port)].is_selected() != True):
            print("             [ACL - Packet Filter] FW IP Test Fail",file = open(file_name, '+a'))
            if_FW_error = True
        if(driver.find_elements(By.NAME, f"rppkfilterREJECT_ARP")[int(port)].is_selected() != True):
            print("             [ACL - Packet Filter] FW ARP Test Fail",file = open(file_name, '+a'))
            if_FW_error = True
        if(driver.find_elements(By.NAME, f"rppkfilterREJECT_NETBIOS")[int(port)].is_selected() != True):
            print("             [ACL - Packet Filter] FW NetBIOS Test Fail",file = open(file_name, '+a'))
            if_FW_error = True
        if(driver.find_elements(By.NAME, f"rppkfilterREJECT_DHCP")[int(port)].is_selected() != True):
            print("             [ACL - Packet Filter] FW DHCP Test Fail",file = open(file_name, '+a'))
            if_FW_error = True
        if(driver.find_elements(By.NAME, f"rppkfilterREJECT_EAPOL")[int(port)].is_selected() != True):
            print("             [ACL - Packet Filter] FW EAPOL Test Fail",file = open(file_name, '+a'))
            if_FW_error = True
        if(driver.find_elements(By.NAME, f"rppkfilterREJECT_IGMP")[int(port)].is_selected() != True):
            print("             [ACL - Packet Filter] FW IGMP Test Fail",file = open(file_name, '+a'))
            if_FW_error = True                        
        # --------------------- FW web check end ------------------
                            
    # EMS Result
    if(if_EMS_error == True):
        print(f"             [ACL - Packet Filter] EMS web check fail",file = open(file_name, '+a'))
    else:
        print(f"             [ACL - Packet Filter] EMS web check pass",file = open(file_name, '+a')) 

    # FW Result
    if(if_FW_error == True):
        print(f"             [ACL - Packet Filter] FW web check fail",file = open(file_name, '+a'))
    else:
        print(f"             [ACL - Packet Filter] FW web check pass",file = open(file_name, '+a')) 

    # Final Result          
    if((if_EMS_error == False) and (if_FW_error == False)):
        print(f"  [EMS1-{output_id}][ACL - Packet Filter] Result Pass",file = open(file_name, '+a'))
        print(f"  [EMS1-6127][ACL - Packet Filter - Apply] Result Pass",file = open(file_name, '+a'))
    else:
        print(f"  [EMS1-{output_id}][ACL - Packet Filter] Result Fail",file = open(file_name, '+a'))
        print(f"  [EMS1-6127][ACL - Packet Filter - Apply] Result Fail",file = open(file_name, '+a'))

@retry()
def EMS_ACL_PPPoE(driver,url,MSC_card,username,password, ems_url, ems_password,file_name):

    print(f"EMS - ACL - PPPoE Test\n",file = open(file_name, '+a'))
    print(f"  [EMS1-6134][ACL - PPPoE Forbidden - Page]",file = open(file_name, '+a'))
    print(f"  [EMS1-6128][ACL - PPPoE - Option 82 Policy Mode - Apply]",file = open(file_name, '+a'))
    print(f"  [EMS1-6129][ACL - PPPoE - New]",file = open(file_name, '+a'))
    print(f"  [EMS1-6133][ACL - PPPoE Forbidden - New]",file = open(file_name, '+a'))
    print(f"  [EMS1-6130][ACL - PPPoE - Modify]",file = open(file_name, '+a'))
    print(f"  [EMS1-6131][ACL - PPPoE - Page]",file = open(file_name, '+a'))
    print(f"  [EMS1-6132][ACL - PPPoE - Delete]",file = open(file_name, '+a'))
    print(f"  [EMS1-6135][ACL - PPPoE Forbidden - Delete]",file = open(file_name, '+a'))

    if_EMS_error = False
    if_FW_error = False
    
    # NEW START ------------------------------------------------------------------------------------------------------------------
    # --------------------- EMS web start ---------------------
    # EMS - ACL - PPPoE 
    if_new_error = False
    if_forb_new_error = False
    if_82_error = False
    driver.get(ems_url)
    time.sleep(5)
    mod.Login_EMS(driver,username,ems_password)
    time.sleep(5)
    EMS_Provision_Config_path(driver,url)
    time.sleep(2)    
    driver.find_element(By.LINK_TEXT, "ACL").click()          
    time.sleep(1)
    driver.find_element(By.LINK_TEXT, "PPPoE").click()
    time.sleep(3)
    # Option 82 Policy Mode Apply Test
    tmp_val = 'VLAN'
    e_acl.PPPoE_Option_82_Policy_Mode(driver,tmp_val)
    e_acl.PPPoE_Option_82_Policy_Mode_Apply(driver)
    msg = alert_accept_text(driver)
    if(if_msg_not_success(msg)):        
        print(f"             [ACL - PPPoE] EMS PPPoE Option 82 Policy Mode set '{tmp_val}' Apply msg:{msg}  Apply Fail",file = open(file_name, '+a'))
        if_EMS_error = True
        if_82_error = True
    else:
        print(f"             [ACL - PPPoE] EMS PPPoE Option 82 Policy Mode set '{tmp_val}' Apply msg:{msg}  Apply Pass",file = open(file_name, '+a'))
    time.sleep(2)

    # vlan input test
    test_keys = ["4095","0","@","4094","4094"]
    for i in test_keys:
        e_acl.PPPoE_New(driver)    
        e_acl.PPPoE_New_Intermediate_Agent_VID(driver,i)
        e_mod.OK(driver)
        time.sleep(1)  
        alert_accept(driver) # "enter"
        if(i != "4094"):
            try:
                driver.find_element(By.ID, "popupClose").click()
                print(f"             [ACL - PPPoE] EMS Intermediate Agent VID invalid:{i} apply Test pass",file = open(file_name, '+a'))            
            except:
                print(f"             [ACL - PPPoE] EMS Intermediate Agent VID invalid:{i} apply Test fail",file = open(file_name, '+a'))
                if_EMS_error = True 
                if_new_error = True
        else:
            try:
                driver.find_element(By.ID, "popupClose").click()
                print(f"             [ACL - PPPoE] EMS Intermediate Agent VID valid:{i} apply Test fail",file = open(file_name, '+a'))            
                if_EMS_error = True 
                if_new_error = True
            except:
                print(f"             [ACL - PPPoE] EMS Intermediate Agent VID valid:{i} apply Test pass",file = open(file_name, '+a'))

    # check 
    # check 4094, and its identical
    count = 0
    if_find = False                                      
    for index in range(driver.find_elements(By.CLASS_NAME, "zy_tr.acl_pppoe_vid_table_row").__len__()):
        if(driver.find_elements(By.CLASS_NAME, "zy_td.acl_pppoe_vid_vid")[index].text == "4094"):
            if_find = True
            count = count + 1 

    if(if_find == False):
        print(f"             [ACL - PPPoE] EMS Intermediate Agent VID not found Test fail",file = open(file_name, '+a'))
        if_EMS_error = True 
        if_new_error = True
    else:
        print(f"             [ACL - PPPoE] EMS Intermediate Agent VID found Test pass",file = open(file_name, '+a'))
    if(count > 1):
        print(f"             [ACL - PPPoE] EMS Intermediate Agent one identical VID Test fail",file = open(file_name, '+a'))
        if_EMS_error = True
        if_new_error = True
    else:
        print(f"             [ACL - PPPoE] EMS Intermediate Agent one identical VID Test pass",file = open(file_name, '+a'))
    

    # input circuit ID, remode ID, policy, linechar
    for index in range(driver.find_elements(By.CLASS_NAME, "zy_tr.acl_pppoe_vid_table_row").__len__()):
        if(driver.find_elements(By.CLASS_NAME, "zy_td.acl_pppoe_vid_vid")[index].text == "4094"):
            table_index = index +1
            e_acl.PPPoE_Select(driver,True,table_index)
            e_acl.PPPoE_Modify(driver)
            time.sleep(2)
            e_acl.PPPoE_New_Circuit_ID_Option_Info(driver,"123456789012345678901234567890123456789012345678901234567890123")
            e_acl.PPPoE_New_Remote_ID_Option_Info(driver,"123456789012345678901234567890123456789012345678901234567890123")
            e_acl.PPPoE_New_Option_Policy(driver,"Keep")
            e_acl.PPPoE_New_Option_Linechar(driver,"Full")
            e_mod.OK(driver)
            time.sleep(1)
            alert_accept(driver) # "enter"
            try:
                driver.find_element(By.ID, "popupClose").click()
                print(f"             [ACL - PPPoE] EMS Intermediate Agent apply Test fail",file = open(file_name, '+a'))            
                if_EMS_error = True 
                if_new_error = True
            except:
                print(f"             [ACL - PPPoE] EMS Intermediate Agent apply Test pass",file = open(file_name, '+a'))
            
            # check 
            e_acl.PPPoE_Select(driver,True,table_index)
            e_acl.PPPoE_Modify(driver)
