def _ACL_Cleanup_Leftover(driver,url,slot,port,username,ems_url,ems_password,file_name):
    """Best-effort: remove ACL rules on slot-port and all ACL profiles left by an aborted attempt,
    so a retry does not fail on duplicate profile names / an open dialog."""
    try:
        driver.get(ems_url)
        time.sleep(1)
        mod.Login_EMS(driver,username,ems_password)
        time.sleep(1)
        EMS_Provision_Config_path(driver,url)
        time.sleep(2)
        driver.find_element(By.LINK_TEXT, "ACL").click()
        time.sleep(1)
        driver.find_element(By.LINK_TEXT, "ACL Rule").click()
        time.sleep(3)
        e_acl.ACL_Rule_Slot(driver,slot)
        e_acl.ACL_Rule_Port(driver,port)
        time.sleep(3)
        if driver.find_elements(By.CLASS_NAME,"zy_td.acl_aclprofile_table_aclprofile").__len__() > 0:
            e_acl.ACL_Rule_Select(driver)
            e_acl.ACL_Rule_Delete(driver)
            msg = alert_accept_text(driver)
            print(f"             [ACL] Pre-test cleanup: removed leftover ACL Rules on {slot}-{port} msg:{msg}",file = open(file_name, '+a'))
            time.sleep(2)
        driver.find_element(By.LINK_TEXT, "ACL Profile").click()
        time.sleep(3)
        if driver.find_elements(By.CLASS_NAME,"zy_td.acl_AclProfile_Name").__len__() > 0:
            e_acl.ACL_Profile_Select(driver)
            e_acl.ACL_Profile_Delete(driver)
            msg = alert_accept_text(driver)
            print(f"             [ACL] Pre-test cleanup: removed leftover ACL Profiles msg:{msg}",file = open(file_name, '+a'))
    except Exception as e:
        print(f"             [ACL] Pre-test cleanup skipped: {str(e).splitlines()[0] if str(e) else repr(e)}",file = open(file_name, '+a'))


@retry()
def EMS_ACL_Rule_Profile(driver,url,list_element,username,password, ems_url, ems_password,file_name):
    
    print(f"EMS - ACL - ACL Rule Test\n",file = open(file_name, '+a'))
    print(f"EMS - ACL - ACL Profile Test\n",file = open(file_name, '+a'))

    slot = list_element.split(",")[1]
    port = list_element.split(",")[2]
    cardtype = list_element.split(",")[3]
    print(f"             ({cardtype} {slot}-{port})",file = open(file_name, '+a'))

    print_list = []
    print_list.append('[EMS1-6136][ACL - ACL Rule - Apply with Profile]')
    print_list.append('[EMS1-6137][ACL - ACL Rule - Apply with Priority]')
    print_list.append('[EMS1-6138][ACL - ACL Rule - Delete]')
    for i in print_list: print(f"  {i}",file = open(file_name, '+a'))

    _ACL_Cleanup_Leftover(driver,url,slot,port,username,ems_url,ems_password,file_name)

    output_id = '0000'
    match list_element[:1]:
        case "1":   # GLC1440 GLC1540
                                       
            EMS_ACL_Rule_Profile_2(driver,url,slot,port,username,password,cardtype, ems_url, ems_password,file_name)                  

        case "2":    # OLC3416B OLC3708 OLC3816
            EMS_ACL_Rule_Profile_1(driver,url,slot,port,username,password, ems_url, ems_password,file_name)                  
            # not_support_test(driver,'ACL - ACL Rule',nosup['ACL - ACL Rule'],slot,url, ems_url, ems_password,file_name,print_list=print_list)
        case "3":     # OLC3416     
            EMS_ACL_Rule_Profile_2(driver,url,slot,port,username,password,cardtype, ems_url, ems_password,file_name)                
            # EMS_ACL_Rule_Profile_1(driver,url,slot,port,username,password, ems_url, ems_password,file_name)                  
            # not_support_test(driver,'ACL - ACL Rule',nosup['ACL - ACL Rule'],slot,url, ems_url, ems_password,file_name,print_list=print_list)
        case "4":      # MSC                       
            EMS_ACL_Rule_Profile_2(driver,url,slot,port,username,password,cardtype, ems_url, ems_password,file_name)                  
            # not_support_test(driver,'ACL - ACL Rule',nosup['ACL - ACL Rule'],slot,url, ems_url, ems_password,file_name,print_list=print_list)
        case _:                
            print(f"             No Action (not in any case)",file = open(file_name, '+a'))
    print("======================================================================================",file = open(file_name, '+a'))

def EMS_ACL_Rule_Profile_1(driver,url,slot,port,username,password, ems_url, ems_password,file_name): # NXP
    if_EMS_error = False
    if_FW_error = False
    if_pro_new_error = False
    if_pro_mode_error = False
    if_pro_modify_error = False
    if_pro_delete_error = False
    if_ru_profile_error = False  # Mode:Profile
    if_ru_priority_error = False # Mode:Port
    if_ru_delete_error = False
    # --------------------- EMS web start ---------------------
    print(f"             [ACL - ACL Profile] EMS (Set ACL Profile and Check)",file = open(file_name, '+a'))
    driver.get(ems_url)
    time.sleep(1)
    mod.Login_EMS(driver,username,ems_password)
    time.sleep(1)
    EMS_Provision_Config_path(driver,url)
    time.sleep(2)    
    driver.find_element(By.LINK_TEXT, "ACL").click()          
