    print(f"             [ACL - ACL Profile] EMS set Source MAC/OUI:10:10:10:10:10:01",file = open(file_name, '+a'))
    print(f"             [ACL - ACL Profile] EMS set Drop:True",file = open(file_name, '+a'))
