@retry()
def EMS_ACL_Host_Protection(driver,url,username,password, ems_url, ems_password,file_name):   # (NoCard)
    print(f"EMS - ACL - Host Protection Test\n",file = open(file_name, '+a'))
    print(f"  [EMS1-7006][ACL - Host Protection]",file = open(file_name, '+a'))

    if_EMS_error = False 
    if_FW_error = False
    driver.get(url) 
    time.sleep(2)
    if_NeoX = True if "NeoX" in driver.title else False
    
    driver.get(ems_url)
    time.sleep(1)
    mod.Login_EMS(driver,username,ems_password)
    time.sleep(1)
    EMS_Provision_Config_path(driver,url)
    time.sleep(2)
    
    if if_NeoX == False:
        try:
            driver.find_element(By.LINK_TEXT, "ACL").click()          
            time.sleep(2)
            driver.find_element(By.LINK_TEXT, "Host Protection").click()
            print(f"             [ACL - Host Protection] EMS Page Found Test Fail",file = open(file_name, '+a'))   
            if_EMS_error = True 
        except:
            print(f"             [ACL - Host Protection] EMS Page Not Found Test Pass",file = open(file_name, '+a'))   
    else:
        time.sleep(1)
        mod.Login_EMS(driver,username,ems_password)
        time.sleep(1)
        EMS_Provision_Config_path(driver,url)
        time.sleep(2)    
        driver.find_element(By.LINK_TEXT, "ACL").click()          
        time.sleep(2)
        driver.find_element(By.LINK_TEXT, "Host Protection").click()
        time.sleep(3)     

        print(f"             [ACL - Host Protection] (Invalid Test)",file = open(file_name, '+a'))   
        keys = ["-1","1","9","501","@"]
        for key in keys:
            e_acl.Host_Protection_Rate_Limit_Setting(driver,key,key,key,key,key,key,key)
            e_acl.Host_Protection_Apply(driver)                                             
            msg = alert_accept_text(driver,30)
            if((if_msg_not_success(msg))):
                print(f"             [ACL - Host Protection] EMS msg:{msg} Rate-limit ({key}) Apply Fail Test Pass",file = open(file_name, '+a'))   
            else:
                print(f"             [ACL - Host Protection] EMS msg:{msg} Rate-limit ({key}) Apply Pass Test Fail",file = open(file_name, '+a'))   
                if_EMS_error = True

        print(f"             [ACL - Host Protection] (Valid Test)",file = open(file_name, '+a'))   
        keys = ["10","500","0"]
        for key in keys:
            e_acl.Host_Protection_Rate_Limit_Setting(driver,key,key,key,key,key,key,key)
            e_acl.Host_Protection_Apply(driver)                                             
            msg = alert_accept_text(driver,30)
            if((if_msg_not_success(msg))):
                print(f"             [ACL - Host Protection] EMS msg:{msg} Rate-limit ({key}) Apply Fail Test Fail",file = open(file_name, '+a'))   
                if_EMS_error = True
            else:
                print(f"             [ACL - Host Protection] EMS msg:{msg} Rate-limit ({key}) Apply Pass Test Pass",file = open(file_name, '+a'))   
            # EMS Check
            time.sleep(1)
            EMS_Provision_Config_path(driver,url)
            time.sleep(2)    
            driver.find_element(By.LINK_TEXT, "ACL").click()          
            time.sleep(1)
            driver.find_element(By.LINK_TEXT, "Host Protection").click()
            time.sleep(3)        
            fields = [
                {"id": "acl_hostprotection_arp_input", "expected": key, "name": "ARP"},
                {"id": "acl_hostprotection_bpdu_input", "expected": key, "name": "BPDU"},
                {"id": "acl_hostprotection_dhcp_input", "expected": key, "name": "DHCP"},
                {"id": "acl_hostprotection_dhcpipv6_input", "expected": key, "name": "DHCPv6"},
                {"id": "acl_hostprotection_icmpv6_input", "expected": key, "name": "ICMPv6"},
                {"id": "acl_hostprotection_igmp_input", "expected": key, "name": "IGMP"},
                {"id": "acl_hostprotection_pppoe_input", "expected": key, "name": "PPPoE"},
            ]    
            for field in fields:
                t = driver.find_element(By.ID, field["id"])
                if field["id"].endswith("_checkbox"):
                    value = t.is_selected()
                elif field["id"].endswith("_combobox"):
                    value = Select(t).first_selected_option.text
                else:
                    value = t.get_attribute("value")
                
                if value != field["expected"]:
                    print(f"             [ACL - Host Protection] EMS {field['name']} Rate-limit ({value}!={field['expected']}) Test Fail", file=open(file_name, '+a'))
                    if_EMS_error = True
                else:
                    print(f"             [ACL - Host Protection] EMS {field['name']} Rate-limit ({field['expected']}) Test Pass", file=open(file_name, '+a'))
            # FW Check
            driver.get(url) 
            time.sleep(3)
            mod.Login(driver,username,password) 
            time.sleep(3)
            mod.Switch_Default(driver)
            mod.Page_Switch(driver,"ACL")
            mod.SubPage_Switch(driver,"Host Protection")
            mod.Switch_Frame(driver)
            time.sleep(3) 
            fields = [
                {"id": "rpaclhostprotect_rateArp", "expected": key, "name": "ARP"},
                {"id": "rpaclhostprotect_rateBpdu", "expected": key, "name": "BPDU"},
                {"id": "rpaclhostprotect_rateDhcp", "expected": key, "name": "DHCP"},
                {"id": "rpaclhostprotect_rateDhcpv6", "expected": key, "name": "DHCPv6"},
                {"id": "rpaclhostprotect_rateIcmpv6", "expected": key, "name": "ICMPv6"},
                {"id": "rpaclhostprotect_rateIgmp", "expected": key, "name": "IGMP"},
                {"id": "rpaclhostprotect_ratePppoe", "expected": key, "name": "PPPoE"},
            ]    
            for field in fields:
                t = driver.find_element(By.NAME, field["id"])
                if field["id"].endswith("_checkbox"):
                    value = t.is_selected()
                elif field["id"].endswith("_combobox"):
                    value = Select(t).first_selected_option.text
                else:
                    value = t.get_attribute("value")
                
                if value != field["expected"]:
                    print(f"             [ACL - Host Protection] FW {field['name']} Rate-limit ({value}!={field['expected']}) Test Fail", file=open(file_name, '+a'))
                    if_FW_error = True
                else:
                    print(f"             [ACL - Host Protection] FW {field['name']} Rate-limit ({field['expected']}) Test Pass", file=open(file_name, '+a'))
            driver.get(ems_url)
            time.sleep(1)
            mod.Login_EMS(driver,username,ems_password)
            time.sleep(1)
            EMS_Provision_Config_path(driver,url)
            time.sleep(2)    
            driver.find_element(By.LINK_TEXT, "ACL").click()          
            time.sleep(1)
            driver.find_element(By.LINK_TEXT, "Host Protection").click()
            time.sleep(3) 
    if ((if_EMS_error == False) and (if_FW_error == False)):
        print(f"  [EMS1-7006][ACL - Host Protection] Result Pass",file = open(file_name, '+a'))
    else:
        print(f"  [EMS1-7006][ACL - Host Protection] Result Fail",file = open(file_name, '+a'))

