def EMS_ACL_MAC_Filter_1(driver,url,slot,port,username,password, ems_url, ems_password,file_name):
    if_EMS_error = False
    if_FW_error = False        
    # --------------------- EMS web start ---------------------
    driver.get(ems_url)
