    mod.Login_EMS(driver,username,ems_password)
    time.sleep(2)    
    EMS_Provision_Config_path(driver,url)
    driver.find_element(By.LINK_TEXT, "ACL").click()          
    time.sleep(1)
    driver.find_element(By.LINK_TEXT, "MAC Filter").click()
    time.sleep(1)
    e_acl.MAC_Filter_Select_Slot(driver,slot)
    e_acl.MAC_Filter_Select_Port(driver,port)
    e_acl.MAC_Filter_Enable(driver,True)
    e_acl.MAC_Filter_Mode(driver,"Accept")
    time.sleep(1)

    keys = ["00:00:00:00:00:0A","00:00:00:00:00:0b"]
    for key in keys:
        e_acl.MAC_Filter_MAC(driver,key,1)
        e_acl.MAC_Filter_Save(driver)
        msg = alert_accept_text(driver)
        if(if_msg_not_success(msg)):
            print(f"             [ACL - MAC Filter] EMS {key} msg:{msg} Apply Fail Test Fail #243804",file = open(file_name, '+a'))        
            if_EMS_error = True
        else:        
            print(f"             [ACL - MAC Filter] EMS {key} msg:{msg} Apply Pass Test Pass",file = open(file_name, '+a'))        
