@retry()
def EMS_Neox_ACL_Loopguard(driver,url,list_element,username,password, ems_url, ems_password,file_name):
    
    print(f"EMS - Neox - ACL - Loopguard Test\n",file = open(file_name, '+a'))

    slot = list_element.split(",")[1]
    port = list_element.split(",")[2]
    cardtype = list_element.split(",")[3]
    print(f"             ({cardtype} {slot}-{port})",file = open(file_name, '+a'))

    print_list = []
    print_list.append('[EMS1-7003][ACL - Loopguard]')
    for i in print_list: print(f"  {i}",file = open(file_name, '+a'))

    match list_element[:1]:            
        case "1":   # GLC1440 GLC1540
            # print(f"             No Action (GLC Case)",file = open(file_name, '+a'))
            EMS_Neox_ACL_Loopguard_2(driver,url,username,password,slot,port, ems_url, ems_password,file_name)
        case "2":    # OLC3416B OLC3708 OLC3816    XPON
            EMS_Neox_ACL_Loopguard_1(driver,url,username,password,slot,port, ems_url, ems_password,file_name)                  
        case "3":     # OLC3416     
            # not_support_test(driver,'ACL - ACL Egress Rule',nosup['ACL - ACL Egress Rule'],slot,url, ems_url, ems_password,file_name,print_list=print_list)
            print(f"             No Action (OLC3416 Case)",file = open(file_name, '+a'))
        case "4":      # MSC                       
            # print(f"             No Action (MSC Case)",file = open(file_name, '+a'))
            EMS_Neox_ACL_Loopguard_2(driver,url,username,password,slot,port, ems_url, ems_password,file_name)
        case _:                
            print(f"             No Action (not in any case)",file = open(file_name, '+a'))

    print("======================================================================================",file = open(file_name, '+a'))

def EMS_Neox_ACL_Loopguard_1(driver,url,username,password,slot,port, ems_url, ems_password,file_name): # NXP
    if_EMS_error = False
    if_FW_error = False        
    # --------------------- EMS web start ---------------------
    driver.get(ems_url)
    time.sleep(2)    
    mod.Login_EMS(driver,username,ems_password)
    time.sleep(2)    
    EMS_Provision_Config_path(driver,url)
    driver.find_element(By.LINK_TEXT, "ACL").click()          
    time.sleep(1)
    driver.find_element(By.LINK_TEXT, "Loopguard").click()
    time.sleep(2)    
    e_acl.Select_Slot(driver,slot)
    e_acl.Select_Port(driver,port)
    time.sleep(2)    
    print(f"             [ACL - Loopguard] EMS Select {slot}-{port}",file = open(file_name, '+a'))
    is_disabled = driver.find_element(By.ID, "acl_loopguard_policy_select").get_attribute("disabled") is not None
    if is_disabled:
        print(f"             [ACL - Loopguard] EMS Policy Detect attribute 'disable' Pass Test Pass",file = open(file_name, '+a'))
    else:
        print(f"             [ACL - Loopguard] EMS Policy Detect attribute 'disable' Fail Test Fail",file = open(file_name, '+a'))
        if_EMS_error = True
    try:
        driver.find_element(By.ID,"acl_loopguard_recover_time_text").send_keys('123')
        print(f"             [ACL - Loopguard] EMS Recover Time Input Pass Test Fail",file = open(file_name, '+a'))
        if_EMS_error = True
    except:
        print(f"             [ACL - Loopguard] EMS Recover Time Input Fail Test Pass",file = open(file_name, '+a'))

    keys = ["Enable","Disable"]
    for key in keys:
        print(f"             [ACL - Loopguard] EMS (set LG Enable : {key})",file = open(file_name, '+a'))
        e_acl.Loopguard_LG_Enable(driver,key)
        e_acl.Loopguard_Apply(driver)
        msg = alert_accept_text(driver)
        if(if_msg_not_success(msg)):        
            print(f"             [ACL - Loopguard] EMS Apply msg:{msg}  Test Fail",file = open(file_name, '+a'))
            if_EMS_error = True
        else:
            print(f"             [ACL - Loopguard] EMS Apply msg:{msg}  Test Pass",file = open(file_name, '+a'))
        tmp = Select(driver.find_element(By.ID,"acl_loopguard_lg_enable_select")).first_selected_option.text
        if(tmp != key):
            print(f"             [ACL - Loopguard] EMS LG Enable ({tmp}!={key}) Test Fail",file = open(file_name, '+a'))
        else:
            print(f"             [ACL - Loopguard] EMS LG Enable ({tmp}) Test Pass",file = open(file_name, '+a'))

        driver.get(url) 
        time.sleep(3)
        mod.Login(driver,username,password)      
        mod.Switch_Default(driver)
        mod.Page_Switch(driver,"ACL")
        mod.SubPage_Switch(driver,"Loopguard")
        mod.Switch_Frame(driver)
        time.sleep(3)    
        driver.find_element(By.XPATH,f"//*[@name='lctbl_selSlot']/option[{slot}]").click()
        time.sleep(1)    
        # driver.find_element(By.XPATH,f"//*[@name='lctbl_selPort']/option[{port}]").click()
        # time.sleep(1)    
        driver.find_element(By.NAME,"lctbl_selLoad").click()
        time.sleep(5)    
        if key == "Enable":
            expect = True
        else:
            expect = False
        tmp = driver.find_elements(By.NAME,"rpacl_lg_enable")[int(port)-1].is_selected()
        if tmp != expect:
            print(f"             [ACL - Loopguard] FW Port {port} LG Enable ({tmp}!={expect}) Test Fail",file = open(file_name, '+a'))
        else:
            print(f"             [ACL - Loopguard] FW Port {port} LG Enable ({tmp}) Test Pass",file = open(file_name, '+a'))

        driver.get(ems_url)
        time.sleep(1)
        EMS_Provision_Config_path(driver,url)
        time.sleep(2)    
        driver.find_element(By.LINK_TEXT, "ACL").click()          
        time.sleep(1)
        driver.find_element(By.LINK_TEXT, "Loopguard").click()
        time.sleep(2)    
        e_acl.Select_Slot(driver,slot)
        e_acl.Select_Port(driver,port)
        time.sleep(2)         

    if(if_EMS_error == True):
        print(f"             [ACL - Loopguard] EMS web check fail",file = open(file_name, '+a'))
    else:
        print(f"             [ACL - Loopguard] EMS web check pass",file = open(file_name, '+a')) 
    if(if_FW_error == True):
        print(f"             [ACL - Loopguard] FW web check fail",file = open(file_name, '+a'))
    else:
        print(f"             [ACL - Loopguard] FW web check pass",file = open(file_name, '+a')) 
    if((if_EMS_error == False) and (if_FW_error == False)):
        print(f"  [EMS1-7003][ACL - Loopguard] Result Pass",file = open(file_name, '+a'))
    else:
        print(f"  [EMS1-7003][ACL - Loopguard] Result Fail",file = open(file_name, '+a'))

