def EMS_Neox_ACL_BPDU_Ctrl_1(driver,url,username,password,slot,port, ems_url, ems_password,file_name): # NXP
    if_EMS_error = False
    if_FW_error = False        
    # --------------------- EMS web start ---------------------
    driver.get(ems_url)
    time.sleep(2)    
    mod.Login_EMS(driver,username,ems_password)
    time.sleep(2)    
    EMS_Provision_Config_path(driver,url)
