    try:
        e_acl.BPDU_Ctrl_Mode(driver,"Network")
        print(f"             [ACL - BPDU Ctrl] EMS Mode Network Select Success Test Fail",file = open(file_name, '+a'))
        if_EMS_error = True
    except:
        print(f"             [ACL - BPDU Ctrl] EMS Mode Network Select Fail Test Pass",file = open(file_name, '+a'))
    
    keys = ["Tunnel","Discard"]
    for key in keys:
        print(f"             [ACL - BPDU Ctrl] EMS (set Mode : {key})",file = open(file_name, '+a'))
        e_acl.BPDU_Ctrl_Mode(driver,key)
        e_acl.BPDU_Ctrl_Apply(driver)
        msg = alert_accept_text(driver)
        if(if_msg_not_success(msg)):        
            print(f"             [ACL - BPDU Ctrl] EMS msg:{msg} Apply Fail Test Fail",file = open(file_name, '+a'))
            if_EMS_error = True
        else:
            print(f"             [ACL - BPDU Ctrl] EMS msg:{msg} Apply Pass Test Pass",file = open(file_name, '+a'))
        tmp = Select(driver.find_element(By.ID,"acl_bptu_mode_select")).first_selected_option.text
