    # and EMS slowdowns made the result unreliable); EMS adds the last entries, then must reject 4001 and show all 4000.
    import module.telnet_module as tel
    cli_fill_end = 3990
    url_ip = url.split("/")[2]
    # VLAN 2~16 (VPN on) are already there from the VPN test above
    cli_errors, cli_sec = tel.bulk_config(url_ip, [f"igmp-mld vlan {v}" for v in range(17, cli_fill_end + 1)], username, password)
    print(f"             [Multicast - VLAN Mode] DUT CLI add VLAN 17~{cli_fill_end}: {len(cli_errors)} error(s), {int(cli_sec)} sec",file = open(file_name, '+a'))
    for cmd, out in cli_errors[:5]:
        print(f"             [Multicast - VLAN Mode] DUT CLI '{cmd}' -> {out!r}",file = open(file_name, '+a'))

    # EMS sync check: reopen the page, last page (VLAN 3981~3990) must show VLAN {cli_fill_end}
    driver.get(ems_url)
    time.sleep(5)
    EMS_Provision_Config_path(driver,url)
    time.sleep(2)
    driver.find_element(By.LINK_TEXT, "Multicast").click()
    time.sleep(1)
