    #             else:
    #                 output_id = '0000'      # GLC1540
                
    #             Multicast_Multicast_MAC_1(driver,url,slot,port,output_id,username,password, ems_url, ems_password,file_name)                  

    #         case "2":
    #             if("3416B" in cardtype):              
    #                 output_id = '0000'      # OLC3416B        
    #             elif ("3708" in cardtype):
    #                 output_id = '0000'      # OLC3708
    #             else:
    #                 output_id = '0000'      # OLC3816
    #             print(f"             {NO_ACTION}",file = open(file_name, '+a'))                 
    #         case "3":
    #             output_id = '0000'          # OLC3416     
