@retry()
def Sys_IPv4_Setup(driver,url,MSC_card,username,password, ems_url, ems_password,file_name):
    print(f"EMS - Sys - IPv4 Setup Test\n",file = open(file_name, '+a')) 
    print(f"  [EMS1-6226][Sys - IPv4 Setup - Inband DHCP - Renew]",file = open(file_name, '+a'))
    print(f"  [EMS1-6227][Sys - IPv4 Setup - Inband DHCP - Release]",file = open(file_name, '+a'))
    print(f"  [EMS1-6228][Sys - IPv4 Setup - Outband DHCP - Renew]",file = open(file_name, '+a'))
    print(f"  [EMS1-6229][Sys - IPv4 Setup - Outband DHCP - Release]",file = open(file_name, '+a'))
    print(f"  [EMS1-6225][Sys - IPv4 Setup - Apply]",file = open(file_name, '+a'))
    if_EMS_error = False
    if_FW_error = False
    if_apply_error = False

    # --------------------- EMS web start ---------------------
    # EMS - Sys - IPv4 Setup

    driver.get(ems_url)
    time.sleep(5)
    mod.Login_EMS(driver,username,ems_password)
    time.sleep(5)    
    EMS_Provision_Config_path(driver,url)
    time.sleep(2)    
    driver.find_element(By.LINK_TEXT, "System").click()          
    time.sleep(1)
    driver.find_element(By.LINK_TEXT, "IPv4 Setup").click()
    time.sleep(3)

    # Sys IP Setup IPv4 Setup

    default_val = []
    default_val.append(driver.find_element(By.ID,"sys_ipv4_pbit_text").get_attribute("value"))
    default_val.append(driver.find_element(By.ID,"sys_ipv4_outband_address_text").get_attribute("value"))
    default_val.append(driver.find_element(By.ID,"sys_ipv4_outband_gateway_text").get_attribute("value"))


    ip_setup_gateway = driver.find_element(By.ID, "sys_ipv4_inband_gateway_text").get_attribute("value")
    # e_sys.IP_Setup_IPv4_Apply(driver)


    e_sys.IP_Setup_IPv4_Inband_Pbit(driver,"7")
    # print(f"             [Sys - General Setup] EMS Outband IP Set Tmp No Apply !!!!! ",file = open(file_name, '+a'))
    # Outband IP/Gateway are disabled while Outband Mode is Dynamic
    if not driver.find_element(By.ID,"sys_ipv4_outband_static_radio").is_selected():
        e_sys.IP_Setup_IPv4_Outband_Mode(driver,"static")
        time.sleep(1)
        print(f"             [System - IPv4 Setup] EMS Set Outband Mode:Static",file = open(file_name, '+a'))
        # Dynamic leaves Outband Mask at 0, Apply needs 1~31
        outband_mask = driver.find_element(By.ID,"sys_ipv4_outband_mask_text").get_attribute("value")
        if not (outband_mask.isdigit() and 1 <= int(outband_mask) <= 31):
            e_sys.IP_Setup_IPv4_Outband_Mask(driver,"24")
            print(f"             [System - IPv4 Setup] EMS Set Outband Mask:24 (was {outband_mask})",file = open(file_name, '+a'))
    e_sys.IP_Setup_IPv4_Outband_IP(driver,"192.168.0.100")
    e_sys.IP_Setup_IPv4_Outband_Gateway(driver,"192.168.0.254")
    e_sys.IP_Setup_IPv4_Apply(driver)
    print(f"             [System - IPv4 Setup] EMS Set Inband Pbit:7, Outband ip:192.168.0.100 gateway:192.168.0.254",file = open(file_name, '+a'))
    msg = alert_accept_text(driver,30)
    if(if_msg_not_success(msg)):
        print(f"             [System - IPv4 Setup] EMS Apply msg:{msg}  Apply Fail",file = open(file_name, '+a'))
        if_EMS_error = True
        if_apply_error = True
    else:
        print(f"             [System - IPv4 Setup] EMS Apply msg:{msg}  Apply Pass",file = open(file_name, '+a'))
    
    EMS_Provision_Config_path(driver,url)
    time.sleep(1)
    driver.find_element(By.LINK_TEXT, "System").click()          
    driver.find_element(By.LINK_TEXT, "IPv4 Setup").click()
    time.sleep(1)
    if(driver.find_element(By.ID,"sys_ipv4_pbit_text").get_attribute("value") != "7"):
        print(f"             [Sys - General Setup] EMS Inband P-bit : {driver.find_element(By.ID,'sys_ipv4_pbit_text').get_attribute('value')}!=7 Test Fail",file = open(file_name, '+a'))
        if_EMS_error = True
        if_apply_error = True
    else:
        print(f"             [Sys - General Setup] EMS Inband P-bit : 7 Test Pass",file = open(file_name, '+a'))
    if(driver.find_element(By.ID,"sys_ipv4_outband_address_text").get_attribute("value") != "192.168.0.100"):
        print(f"             [Sys - General Setup] EMS Outband IP Address : {driver.find_element(By.ID,'sys_ipv4_outband_address_text').get_attribute('value')}!=192.168.0.100 Test Fail",file = open(file_name, '+a'))
        if_EMS_error = True
        if_apply_error = True
    else:
        print(f"             [Sys - General Setup] EMS Outband IP Address : 192.168.0.100 Test Pass",file = open(file_name, '+a'))    
    if(driver.find_element(By.ID,"sys_ipv4_outband_gateway_text").get_attribute("value") != "192.168.0.254"):
        print(f"             [Sys - General Setup] EMS Outband Gateway : {driver.find_element(By.ID,'sys_ipv4_outband_gateway_text').get_attribute('value')}!=192.168.0.254 Test Fail",file = open(file_name, '+a'))
        if_EMS_error = True
        if_apply_error = True
    else:
        print(f"             [Sys - General Setup] EMS Outband Gateway : 192.168.0.254 Test Pass",file = open(file_name, '+a'))    
    
    e_sys.IP_Setup_IPv4_Inband_Renew(driver)
    msg = alert_accept_text(driver,30)
    if(if_msg_not_success(msg)):
        print(f"             [System - IPv4 Setup] EMS Inband Renew Button msg:{msg}  Test Fail",file = open(file_name, '+a'))
        print(f"  [EMS1-6226][Sys - IPv4 Setup - Inband DHCP - Renew] Result Fail",file = open(file_name, '+a'))
        if_EMS_error = True
    else:
        print(f"             [System - IPv4 Setup] EMS Inband Renew Button msg:{msg}  Test Pass",file = open(file_name, '+a'))
        print(f"  [EMS1-6226][Sys - IPv4 Setup - Inband DHCP - Renew] Result Pass",file = open(file_name, '+a'))
        
    e_sys.IP_Setup_IPv4_Inband_Release(driver)
    msg = alert_accept_text(driver,30)
    if(if_msg_not_success(msg)):
        print(f"             [System - IPv4 Setup] EMS Inband Release Button msg:{msg}  Test Fail",file = open(file_name, '+a'))
        print(f"  [EMS1-6227][Sys - IPv4 Setup - Inband DHCP - Release] Result Fail",file = open(file_name, '+a'))
        if_EMS_error = True
    else:
        print(f"             [System - IPv4 Setup] EMS Inband Release Button msg:{msg}  Test Pass",file = open(file_name, '+a'))
        print(f"  [EMS1-6227][Sys - IPv4 Setup - Inband DHCP - Release] Result Pass",file = open(file_name, '+a'))
                    
    e_sys.IP_Setup_IPv4_Outband_Renew(driver)
    msg = alert_accept_text(driver,30)
    if(if_msg_not_success(msg)):
        print(f"             [System - IPv4 Setup] EMS Outband Renew Button msg:{msg}  Test Fail",file = open(file_name, '+a'))
        print(f"  [EMS1-6228][Sys - IPv4 Setup - Outband DHCP - Renew] Result Fail",file = open(file_name, '+a'))
        if_EMS_error = True
    else:
        print(f"             [System - IPv4 Setup] EMS Outband Renew Button msg:{msg}  Test Pass",file = open(file_name, '+a'))
        print(f"  [EMS1-6228][Sys - IPv4 Setup - Outband DHCP - Renew] Result Pass",file = open(file_name, '+a'))

    e_sys.IP_Setup_IPv4_Outband_Release(driver)
    msg = alert_accept_text(driver,30)
    if(if_msg_not_success(msg)):
        print(f"             [System - IPv4 Setup] EMS Outband Release Button msg:{msg}  Test Fail",file = open(file_name, '+a'))
        print(f"  [EMS1-6229][Sys - IPv4 Setup - Outband DHCP - Release] Result Fail",file = open(file_name, '+a'))
        if_EMS_error = True
    else:
        print(f"             [System - IPv4 Setup] EMS Outband Release Button msg:{msg}  Test Pass",file = open(file_name, '+a'))
        print(f"  [EMS1-6229][Sys - IPv4 Setup - Outband DHCP - Release] Result Pass",file = open(file_name, '+a'))    
    # --------------------- EMS web end -----------------------
    # --------------------- FW web start ----------------------
    # Sys > IP Setup  > IPv4 Setup
    driver.get(url) 
    time.sleep(3)
    mod.Login(driver,username,password)      
    # 路徑導向 Sys > IP Setup > IPv4 Setup
    mod.Switch_Default(driver)
    mod.Page_Switch(driver,"Sys")
    mod.SubPage_Switch(driver,"IP Setup")
    mod.Switch_Frame(driver)
    mod.Tab_Switch(driver,"IPv4 Setup")
    time.sleep(1)
    if(driver.find_element(By.NAME,"rpsysipsetup_inband_pbit").get_attribute('value') != "7"):
        print(f"             [Sys - General Setup] FW Inband P-bit : {driver.find_element(By.NAME,'rpsysipsetup_inband_pbit').get_attribute('value')}!=7 Test Fail",file = open(file_name, '+a'))
        if_EMS_error = True
        if_apply_error = True
    else:
        print(f"             [Sys - General Setup] FW Inband P-bit : 7 Test Pass",file = open(file_name, '+a'))
    if(driver.find_element(By.NAME,"rpsysipsetup_outband_ip_address").get_attribute('value') != "192.168.0.100"):
        print(f"             [Sys - General Setup] FW Outband IP Address : {driver.find_element(By.NAME,'rpsysipsetup_outband_ip_address').get_attribute('value')}!=192.168.0.100 Test Fail",file = open(file_name, '+a'))
        if_EMS_error = True
        if_apply_error = True
    else:
        print(f"             [Sys - General Setup] FW Outband IP Address : 192.168.0.100 Test Pass",file = open(file_name, '+a'))    
    if(driver.find_element(By.NAME,"rpsysipsetup_outband_gateway").get_attribute('value') != "192.168.0.254"):
        print(f"             [Sys - General Setup] FW Outband Gateway : {driver.find_element(By.NAME,'rpsysipsetup_outband_gateway').get_attribute('value')}!=192.168.0.254 Test Fail",file = open(file_name, '+a'))
        if_EMS_error = True
        if_apply_error = True
    else:
        print(f"             [Sys - General Setup] FW Outband Gateway : 192.168.0.254 Test Pass",file = open(file_name, '+a'))    
    # --------------------- FW web end ------------------------

    # Set to Default Value
    # --------------------- EMS web start ---------------------
    # EMS - Sys - IPv4 Setup
    driver.get(ems_url)
    time.sleep(5)
    mod.Login_EMS(driver,username,ems_password)
    time.sleep(5)    
    EMS_Provision_Config_path(driver,url)
    time.sleep(2)    
    driver.find_element(By.LINK_TEXT, "System").click()          
    time.sleep(1)
    driver.find_element(By.LINK_TEXT, "IPv4 Setup").click()
    time.sleep(1)
    e_sys.IP_Setup_IPv4_Inband_Pbit(driver,default_val[0])
    if driver.find_element(By.ID,"sys_ipv4_outband_address_text").is_enabled():
        e_sys.IP_Setup_IPv4_Outband_IP(driver,default_val[1])
        e_sys.IP_Setup_IPv4_Outband_Gateway(driver,default_val[2])
    default_val.clear()
    # --------------------- EMS web end -----------------------


    # EMS Result
    if(if_EMS_error == True):
        print(f"             [Sys - IPv4 Setup] EMS web check fail",file = open(file_name, '+a'))
    else:
        print(f"             [Sys - IPv4 Setup] EMS web check pass",file = open(file_name, '+a')) 

    # FW Result
    if(if_FW_error == True):
        print(f"             [Sys - IPv4 Setup] FW web check fail",file = open(file_name, '+a'))
    else:
        print(f"             [Sys - IPv4 Setup] FW web check pass",file = open(file_name, '+a')) 

    if not if_apply_error:
        print(f"  [EMS1-6225][Sys - IPv4 Setup - Apply] Result Pass",file = open(file_name, '+a'))
    else:
        print(f"  [EMS1-6225][Sys - IPv4 Setup - Apply] Result Fail",file = open(file_name, '+a'))

    # Final Result
    if("XB" in MSC_card):
        output_id = "0000"
    elif("XA" in MSC_card):
        output_id = "0000"
    elif("QA" in MSC_card):
        output_id = "0000"
    else:
        output_id = "0000"        
    tmp = 'Fail' 
    if((if_EMS_error == False) and (if_FW_error == False)):
        tmp = 'Pass' 
        print(f"  [EMS1-{output_id}][Sys - IPv4 Setup] Result Pass",file = open(file_name, '+a'))
    else:
        print(f"  [EMS1-{output_id}][Sys - IPv4 Setup] Result Fail",file = open(file_name, '+a'))
    # print(f"  [EMS1-6225][Sys - IPv4 Setup - Apply] Result {tmp}",file = open(file_name, '+a'))
    # print(f"  [EMS1-6226][Sys - IPv4 Setup - Inband DHCP - Renew] Result {tmp}",file = open(file_name, '+a'))
    # print(f"  [EMS1-6227][Sys - IPv4 Setup - Inband DHCP - Release] Result {tmp}",file = open(file_name, '+a'))
    # print(f"  [EMS1-6228][Sys - IPv4 Setup - Outband DHCP - Renew] Result {tmp}",file = open(file_name, '+a'))
    # print(f"  [EMS1-6229][Sys - IPv4 Setup - Outband DHCP - Release] Result {tmp}",file = open(file_name, '+a'))
    print("======================================================================================",file = open(file_name, '+a'))

    return ip_setup_gateway

