@retry()
def Switch_General(driver,url,MSC_card,username,password, ems_url, ems_password,file_name):
    print(f"EMS - Switch - General Test\n",file = open(file_name, '+a')) 
    print(f"  [EMS1-6246][Switch - General - Queue Setting - Apply]",file = open(file_name, '+a'))
    print(f"  [EMS1-6247][Switch - General - Aging Time]",file = open(file_name, '+a'))
    if_EMS_error = False
    if_FW_error = False

    # --------------------- EMS web start ---------------------
    # EMS - Switch - General
    
    # EMS website > login
    driver.get(ems_url)
    time.sleep(5)
    mod.Login_EMS(driver,username,ems_password)
    time.sleep(5)    
    EMS_Provision_Config_path(driver,url)
    time.sleep(2)    
    driver.find_element(By.LINK_TEXT, "Switch").click()          
    time.sleep(1)
    driver.find_element(By.LINK_TEXT, "General").click()
    time.sleep(3)

    # Switch Setup General Test 1
    # set priority 0-7:8 
    for test_priority in range(8):
        e_swi.Switch_General_Priority(driver,test_priority,"8")
    e_swi.Switch_General_Apply_1(driver)    
    msg = alert_accept_text(driver)
    if(if_msg_not_success(msg)):
        print(f"             [Switch - General] EMS msg:{msg} Priority apply fail",file = open(file_name, '+a'))
        if_EMS_error = True        
    # check
    for test_priority in range(8):   
        if(driver.find_element(By.XPATH, f"//*[@id='sw_general_queue{test_priority}']/option[8]").is_selected() != True):
            print(f"             [Switch - General] EMS Priority{test_priority} Test Fail",file = open(file_name, '+a'))
            if_EMS_error = True
    
    # Switch Setup General Test 2
    # set aging time 9, 3601, @, 3600,
    test_keys = ["9","3601","@","3600"]
    for val in test_keys:
        e_swi.Switch_Setup_General_Aging_Time(driver,val)
        e_swi.Switch_General_Apply_2(driver)
        msg = alert_accept_text(driver)
        if(val != '3600'):                   # invalid
            if(if_msg_not_success(msg)):
                print(f"             [Switch - General] EMS msg:{msg} Aging time:{val} apply msg pass",file = open(file_name, '+a'))
            else:
                print(f"             [Switch - General] EMS msg:{msg} Aging time:{val} apply msg fail",file = open(file_name, '+a'))
                if_EMS_error = True
        else:
            if(if_msg_not_success(msg)):     # valid
                print(f"             [Switch - General] EMS msg:{msg} Aging time:{val} apply msg fail",file = open(file_name, '+a'))
                if_EMS_error = True
            else:     
                print(f"             [Switch - General] EMS msg:{msg} Aging time:{val} apply msg pass",file = open(file_name, '+a'))
                if(driver.find_element(By.ID, "sw_general_agingiime_text").get_attribute("value") != "3600"):
                    print(f"             [Switch - General] EMS Aging time:{val} Test Fail",file = open(file_name, '+a'))
                    if_EMS_error = True
                else:
                    print(f"             [Switch - General] EMS Aging time:{val} Test Pass",file = open(file_name, '+a'))
                        
    # --------------------- EMS web end -----------------------
    # --------------------- FW web start ----------------------
    # Switch > Switch Setup > General
    driver.get(url) 
    time.sleep(3)
    mod.Login(driver,username,password)      
    # 路徑導向 Switch > Switch Setup > General
    mod.Switch_Default(driver)
    mod.Page_Switch(driver,"Switch")
    mod.SubPage_Switch(driver,"Switch Setup")
    mod.Switch_Frame(driver)
    mod.Tab_Switch(driver,"General")
    time.sleep(3)

    # check priority
    for test_priority in range(8):
        if(driver.find_element(By.XPATH, f"//*[@name='rpsw_setup_general_slt_queue_{test_priority}']/option[8]").is_selected() != True):
            print(f"             [Switch - Switch Setup - General] FW Priority{test_priority} Test Fail",file = open(file_name, '+a'))
            if_FW_error = True

    # check aging time
    if(driver.find_element(By.NAME, f"rpsw_setup_general_ipt_aging_time").get_attribute("value") != "3600"):
        print(f"             [Switch - Switch Setup - General] FW Aging Time:3600 Test Fail",file = open(file_name, '+a'))
        if_FW_error = True    

    # --------------------- FW web end ------------------------
    

    # EMS Result
    if(if_EMS_error == True):
        print(f"             [Switch - General] EMS web check fail",file = open(file_name, '+a'))
    else:
        print(f"             [Switch - General] EMS web check pass",file = open(file_name, '+a')) 

    # FW Result
    if(if_FW_error == True):
        print(f"             [Switch - General] FW web check fail",file = open(file_name, '+a'))
    else:
        print(f"             [Switch - General] FW web check pass",file = open(file_name, '+a')) 

    # Final Result
    if("XB" in MSC_card):
        output_id = "0000"
    elif("XA" in MSC_card):
        output_id = "0000"
    elif("QA" in MSC_card):
        output_id = "0000"
    else:
        output_id = "0000"    
    tmp = 'Fail'     
    if((if_EMS_error == False) and (if_FW_error == False)):
        tmp = 'Pass'     
        print(f"  [EMS1-{output_id}][Switch - General] Result Pass",file = open(file_name, '+a'))
    else:
        print(f"  [EMS1-{output_id}][Switch - General] Result Fail",file = open(file_name, '+a'))
    print(f"  [EMS1-6246][Switch - General - Queue Setting - Apply]  Result {tmp}",file = open(file_name, '+a'))
    print(f"  [EMS1-6247][Switch - General - Aging Time] Result {tmp}",file = open(file_name, '+a'))
    print("======================================================================================",file = open(file_name, '+a'))

