    #     print(f"             ({list_element})",file = open(file_name, '+a'))        
    #     slot = list_element.split(",")[1]
    #     port = list_element.split(",")[2]
    #     cardtype = list_element.split(",")[3]
    #     # print(f"Now in case:{list_element[:1]},  Slot-Port:{slot}-{port}, {cardtype}")
    #     print(f"             Now in case:{list_element[:1]},  Slot-Port:{slot}-{port}, {cardtype}",file = open(file_name, '+a'))

    #     match list_element[:1]:            
    #         case "1":
    #             if("1440" in cardtype):              
    #                 output_id = '0000'      # GLC1440
    #             else:
    #                 output_id = '0000'      # GLC1540
                
    #             Switch_DSCP_1(driver,url,slot,port,output_id,username,password, ems_url, ems_password,file_name)                  

    #         case "2":
    #             if("3416B" in cardtype):              
    #                 output_id = '0000'      # OLC3416B        
    #             elif ("3708" in cardtype):
    #                 output_id = '0000'      # OLC3708
    #             else:
    #                 output_id = '0000'      # OLC3816
    #             print(f"             {NO_ACTION}",file = open(file_name, '+a'))                 
    #         case "3":
    #             output_id = '0000'          # OLC3416     
    #             print(f"             {NO_ACTION}",file = open(file_name, '+a'))             
    #         case _:                
    #             print(f"             No Action (not in any case)",file = open(file_name, '+a'))                           
    #     print(f"",file = open(file_name, '+a'))
    slot = list_element.split(",")[1]
    port = list_element.split(",")[2]
    cardtype = list_element.split(",")[3]
    print(f"             ({cardtype} {slot}-{port})",file = open(file_name, '+a'))

    print_list = []
    print_list.append('[EMS1-6254][Switch - DSCP - Priority Setting - Apply]')
    print_list.append('[EMS1-6255][Switch - DSCP - Port Setting - Apply]')
    for i in print_list: print(f"  {i}",file = open(file_name, '+a'))

    if list_element[:1] in ("1", "4"):
        driver.get(url)
        time.sleep(2)
        if "NeoX" not in driver.title:
            Switch_DSCP_IES(driver,url,slot,'0000',username,password, ems_url, ems_password,file_name)
            print("======================================================================================",file = open(file_name, '+a'))
            return

    match list_element[:1]:
        case "1":
            if("1440" in cardtype):
                output_id = '0000'      # GLC1440
            else:
                output_id = '0000'      # GLC1540

            Switch_DSCP_1(driver,url,slot,port,output_id,username,password, ems_url, ems_password,file_name)

        case "2":
            if("3416B" in cardtype):              
                output_id = '0000'      # OLC3416B        
            elif ("3708" in cardtype):
                output_id = '0000'      # OLC3708
            else:
                output_id = '0000'      # OLC3816
            not_support_test(driver,'Switch - DSCP',nosup['Switch - DSCP'],slot,url, ems_url, ems_password,file_name,print_list=print_list)   
        case "3":
            output_id = '0000'          # OLC3416     
            not_support_test(driver,'Switch - DSCP',nosup['Switch - DSCP'],slot,url, ems_url, ems_password,file_name,print_list=print_list)           
        case "4":                
            output_id = '0000'          # MSC
            # not_support_test(driver,'Switch - DSCP',nosup['Switch - DSCP'],slot,url, ems_url, ems_password,file_name,print_list=print_list)           
            Switch_DSCP_2(driver,url,slot,port,output_id,username,password, ems_url, ems_password,file_name)        
        case _:                
            print(f"             No Action (not in any case)",file = open(file_name, '+a'))  
    print("======================================================================================",file = open(file_name, '+a'))

