def Switch_DSCP_IES(driver,url,slot,output_id,username,password, ems_url, ems_password,file_name): # IES52xx MSC / GLC
    # IES52xx EMS page sets one port at a time (Port combobox + "DSCP Port Enable" checkbox),
    # not the NeoX per-port table with an "all" select.
    if_EMS_error = False
    if_FW_error = False

    def fw_dscp_states():
        driver.get(url)
        time.sleep(3)
        mod.Login(driver,username,password)
        mod.Switch_Default(driver)
        mod.Page_Switch(driver,"Switch")
        mod.SubPage_Switch(driver,"Switch Setup")
        mod.Switch_Frame(driver)
        mod.Tab_Switch(driver,"DSCP")
        swi.Switch_Setup_DSCP_Slot_Select(driver,slot)
        time.sleep(1)
        states = {}
        while True:
            try:
                states[len(states) + 1] = driver.find_element(By.NAME, f"dscp_port{len(states)}").is_selected()
            except:
                break
        return states

    def ems_open():
        driver.get(ems_url)
        time.sleep(5)
        mod.Login_EMS(driver,username,ems_password)
        time.sleep(5)
        EMS_Provision_Config_path(driver,url)
        time.sleep(2)
        driver.find_element(By.LINK_TEXT, "Switch").click()
        time.sleep(1)
        driver.find_element(By.LINK_TEXT, "DSCP").click()
        time.sleep(3)
        e_mod.Wait_Block(driver)
        e_swi.Switch_DSCP_Slot_Select(driver,slot)
        time.sleep(2)
        e_mod.Wait_Block(driver)

    def ems_select_port(port):
        e_swi.Switch_DSCP_Port_Select(driver,port)
        time.sleep(2)
        e_mod.Wait_Block(driver)

    def ems_set_ports(ports, enable):
        ems_open()
        for port in ports:
            ems_select_port(port)
            e_swi.Switch_DSCP_Port_Enable(driver,enable)
            driver.find_element(By.ID, "sw_dscp_port_apply").click()
            msg = alert_accept_text(driver)
            if if_msg_not_success(msg):
                print(f"             [Switch - DSCP] EMS Slot{slot} Port{port} DSCP Port Enable:{enable} Apply msg:{msg} Test Fail",file = open(file_name, '+a'))
                return False
        return True

    orig = fw_dscp_states()
    if not orig:
        print(f"             [Switch - DSCP] FW Slot{slot} no DSCP port found Test Fail",file = open(file_name, '+a'))
        print(f"  [EMS1-6255][Switch - DSCP - Port Setting - Apply] Result Fail",file = open(file_name, '+a'))
        return
    all_ports = sorted(orig)
    test_ports = all_ports if len(all_ports) <= 8 else [all_ports[0], all_ports[1], all_ports[-1]]
    print(f"             [Switch - DSCP] Slot{slot} ports:{len(all_ports)} test ports:{test_ports}",file = open(file_name, '+a'))

    ems_open()
    ems_ports = [o.get_attribute("value") for o in Select(driver.find_element(By.ID, "sw_dscp_port_combobox")).options if o.get_attribute("value") != "NONE"]
    if ems_ports != [str(p) for p in all_ports]:
        print(f"             [Switch - DSCP] EMS Slot{slot} Port list {ems_ports} != FW {all_ports} Test Fail",file = open(file_name, '+a'))
        if_EMS_error = True
    else:
        print(f"             [Switch - DSCP] EMS Slot{slot} Port list {ems_ports} Test Pass",file = open(file_name, '+a'))

    for enable in [True, False]:
        if not ems_set_ports(test_ports, enable):
            if_EMS_error = True
        # EMS read back
        ems_open()
        for port in test_ports:
            ems_select_port(port)
            tmp = driver.find_element(By.ID, "sw_dscp_enable_checkbox").is_selected()
            if tmp != enable:
                print(f"             [Switch - DSCP] EMS Slot{slot} Port{port} DSCP Port Enable {tmp}!={enable} Test Fail",file = open(file_name, '+a'))
                if_EMS_error = True
        print(f"             [Switch - DSCP] EMS DSCP Port Enable:{enable} check done",file = open(file_name, '+a'))
        # FW check
        fw = fw_dscp_states()
        for port in test_ports:
            if fw.get(port) != enable:
                print(f"             [Switch - Switch Setup - DSCP] FW Slot{slot} Port{port} Check Box {fw.get(port)}!={enable} Test Fail",file = open(file_name, '+a'))
                if_FW_error = True
        print(f"             [Switch - Switch Setup - DSCP] FW Port Check Box:{enable} check done",file = open(file_name, '+a'))

    # restore ports that were enabled before the test
    restore = [p for p in test_ports if orig[p]]
    if restore:
        ems_set_ports(restore, True)
        print(f"             [Switch - DSCP] EMS restore DSCP Port Enable on ports {restore}",file = open(file_name, '+a'))

    if(if_EMS_error == True):
        print(f"             [Switch - DSCP] EMS web check fail",file = open(file_name, '+a'))
    else:
        print(f"             [Switch - DSCP] EMS web check pass",file = open(file_name, '+a'))
    if(if_FW_error == True):
        print(f"             [Switch - DSCP] FW web check fail",file = open(file_name, '+a'))
    else:
        print(f"             [Switch - DSCP] FW web check pass",file = open(file_name, '+a'))
    if((if_EMS_error == False) and (if_FW_error == False)):
        print(f"  [EMS1-6255][Switch - DSCP - Port Setting - Apply] Result Pass",file = open(file_name, '+a'))
    else:
        print(f"  [EMS1-6255][Switch - DSCP - Port Setting - Apply] Result Fail",file = open(file_name, '+a'))

