def Switch_DSCP_Priority_Mapping(driver,url,username,password, ems_url, ems_password,file_name): # NoCard
    print(f"EMS - Switch - DSCP Priority Mapping Test\n",file = open(file_name, '+a'))    
    print(f"  [EMS1-6254][Switch - DSCP - Priority Setting - Apply]",file = open(file_name, '+a'))
    
    if_EMS_error = False
    if_FW_error = False

    # 0 Test -------------------------------------------------------------------
    driver.get(ems_url)
    time.sleep(5)
    mod.Login_EMS(driver,username,ems_password)
    time.sleep(5)    
    EMS_Provision_Config_path(driver,url)
    time.sleep(2)    
    driver.find_element(By.LINK_TEXT, "Switch").click()          
    time.sleep(1)
    driver.find_element(By.LINK_TEXT, "DSCP").click()
    time.sleep(5)
    # 0
    for i in range(64):
        e_swi.Switch_DSCP_Mapping(driver,i,'0') 
    time.sleep(1)
    for i in range(64):
        e_swi.Switch_DSCP_Mapping(driver,i,'0')         
    time.sleep(1)
    e_swi.Switch_DSCP_Apply_1(driver)
    alert_accept(driver)
    for mapping_name in range(64):        
        temp = Select(driver.find_element(By.NAME,f"sw_dscp_{mapping_name}")).first_selected_option.get_attribute("value")
        if(temp != '0'):            
            print(f"             [Switch - DSCP] EMS Codepoint{int(mapping_name/10)*10} Priority{mapping_name%10} : 0 Test Fail",file = open(file_name, '+a'))
            if_EMS_error = True
    print(f"             [Switch - DSCP] EMS DSCP Priority Mapping:0 check done",file = open(file_name, '+a'))
    
    driver.get(url) 
    time.sleep(3)
    mod.Login(driver,username,password)      
    # 路徑導向 Switch > Switch Setup > DSCP
    mod.Switch_Default(driver)
    mod.Page_Switch(driver,"Switch")
    mod.SubPage_Switch(driver,"Switch Setup")
    mod.Switch_Frame(driver)
    mod.Tab_Switch(driver,"DSCP")
    # swi.Switch_Setup_DSCP_Slot_Select(driver,slot)
    time.sleep(1)
    for mapping_name in range(64):
        if(driver.find_element(By.XPATH, f"//*[@name='rpsw_setup_dscp_slt_priority_{mapping_name}']/option[1]").is_selected() != True):
            print(f"             [Switch - Switch Setup - DSCP] FW Codepoint{int(mapping_name/10)*10} Priority{mapping_name%10} : 0 Test Fail",file = open(file_name, '+a'))
            if_FW_error = True
    print(f"             [Switch - DSCP] FW DSCP Priority Mapping:0 check done",file = open(file_name, '+a'))



    # 7 Test -------------------------------------------------------------------
