def Switch_Storm_Control_1(driver,url,slot,port,cardtype,output_id,username,password, ems_url, ems_password,file_name,Num=0):
    if_EMS_error = False
    if_FW_error = False

    # (only set % port)
    # Switch 
    # --------------------- EMS web start ---------------------
    # EMS - Switch - Storm Control
    
    # EMS website > login
    driver.get(ems_url)
    time.sleep(5)
    mod.Login_EMS(driver,username,ems_password)
    time.sleep(5)    
    EMS_Provision_Config_path(driver,url)
    time.sleep(2)    
    driver.find_element(By.LINK_TEXT, "Switch").click()          
    time.sleep(1)
    driver.find_element(By.LINK_TEXT, "Storm Control").click()
    time.sleep(3)

    storm_control_num = Num
    # storm_control_num = 0 
    # if("1440" in cardtype):
    #     storm_control_num = 1000000
    # elif("1540" in cardtype):
    #     storm_control_num = 10000000
    # else:
