    #     print(f"             [Switch - Switch Setup - Storm Control] GLC Name Unrecognizable Test Fail",file = open(file_name, '+a'))
    #     if_EMS_error = True
    

    # for test_port in range(1,41):
    #     try:
    test_port = port
    e_swi.Switch_Storm_Control_Slot_Select(driver,slot)
    e_swi.Switch_Storm_Control_Port_Select(driver,str(test_port))
    time.sleep(1)
    e_swi.Switch_Storm_Control_Broadcast(driver,storm_control_num)
    time.sleep(1)
    e_swi.Switch_Storm_Control_DLF(driver,storm_control_num)
    time.sleep(1)
    e_swi.Switch_Storm_Control_Multicast(driver,storm_control_num)
    time.sleep(3)
    e_swi.Switch_Setup_Storm_Control_Save(driver)
    msg = alert_accept_text(driver)
    if(if_msg_not_success(msg)):
        print(f"             [Switch - Storm Control] EMS Port{test_port} Set {storm_control_num} Apply msg:{msg} Test Fail",file = open(file_name, '+a'))
        if_EMS_error = True
    else:
        print(f"             [Switch - Storm Control] EMS Port{test_port} Set {storm_control_num} Apply msg:{msg} Test Pass",file = open(file_name, '+a'))
    
    # check broadcast
    temp = driver.find_element(By.ID ,"sw_stormctrl_broadcast_text").get_attribute("value")
    if(temp != str(storm_control_num)):
        print(f"             [Switch - Storm Control] EMS Port{test_port} Broadcast Test Fail ({temp}!={storm_control_num})",file = open(file_name, '+a'))
        if_EMS_error = True
    # check DLF
    temp = driver.find_element(By.ID ,"sw_stormctrl_def_text").get_attribute("value")
    if(temp != str(storm_control_num)):
        print(f"             [Switch - Storm Control] EMS Port{test_port} DLF Test Fail ({temp}!={storm_control_num})",file = open(file_name, '+a'))
        if_EMS_error = True
    # check Multicast
    temp = driver.find_element(By.ID ,"sw_stormctrl_multi_text").get_attribute("value")
    if(temp != str(storm_control_num)):
        print(f"             [Switch - Storm Control] EMS Port{test_port} Multicast Test Fail ({temp}!={storm_control_num})",file = open(file_name, '+a'))
        if_EMS_error = True
    print(f"             [Switch - Storm Control] EMS port {test_port} Broadcast, DLF, Multicast valid value check done",file = open(file_name, '+a'))
        # except:
        #     pass

    # print(f"             [Switch - Storm Control] EMS all port Broadcast, DLF, Multicast valid value check done",file = open(file_name, '+a'))
    # --------------------- EMS web end -----------------------

    # only check %port
    # --------------------- FW web start ----------------------
    # Switch > Switch Setup > Storm Control
    driver.get(url) 
    time.sleep(3)
    mod.Login(driver,username,password)      
    # 路徑導向 Switch > Switch Setup > Storm Control
    mod.Switch_Default(driver)
    mod.Page_Switch(driver,"Switch")
    mod.SubPage_Switch(driver,"Switch Setup")
    mod.Switch_Frame(driver)
    mod.Tab_Switch(driver,"Storm Control")

    # slot select
    time.sleep(1)
    swi.Switch_Setup_Storm_Control_Slot_Select(driver,slot)
    time.sleep(1)

    # check
    if(driver.find_element(By.NAME, f"rpsw_setup_storm_control_ipt_broadcast{int(port)-1}").get_attribute("value") != str(storm_control_num)):
        print(f"             [Switch - Switch Setup - Storm Control] FW Port{port} Broadcast Test Fail",file = open(file_name, '+a'))
        if_FW_error = True
    if(driver.find_element(By.NAME, f"rpsw_setup_storm_control_ipt_dlf{int(port)-1}").get_attribute("value") != str(storm_control_num)):
        print(f"             [Switch - Switch Setup - Storm Control] FW Port{port} DLF Test Fail",file = open(file_name, '+a'))
        if_FW_error = True
    if(driver.find_element(By.NAME, f"rpsw_setup_storm_control_ipt_multicast{int(port)-1}").get_attribute("value") != str(storm_control_num)):
        print(f"             [Switch - Switch Setup - Storm Control] FW Port{port} Multicast Test Fail",file = open(file_name, '+a'))
        if_FW_error = True    

    print(f"             [Switch - Switch Setup - Storm Control] FW Port{port} valid value check done",file = open(file_name, '+a'))


    # --------------------- FW web end ------------------------

    # max+1 Test
    # --------------------- EMS web start ---------------------
    # EMS - Switch - Storm Control
    
    # EMS website > login
    driver.get(ems_url)
    time.sleep(5)
    mod.Login_EMS(driver,username,ems_password)
    time.sleep(5)    
    EMS_Provision_Config_path(driver,url)
    time.sleep(2)    
    driver.find_element(By.LINK_TEXT, "Switch").click()          
    time.sleep(1)
    driver.find_element(By.LINK_TEXT, "Storm Control").click()
    time.sleep(3)

    # broadcast: max+1 test     (%slot %port)
    e_swi.Switch_Storm_Control_Slot_Select(driver,slot)
    time.sleep(3)
    e_swi.Switch_Storm_Control_Port_Select(driver,port)
    time.sleep(3)
    e_swi.Switch_Storm_Control_Broadcast(driver,storm_control_num+1)
    time.sleep(3)
    e_swi.Switch_Setup_Storm_Control_Save(driver)
    msg = alert_accept_text(driver)
    print(f"             [Switch - Storm Control] EMS Broadcast invalid:{storm_control_num+1} msg:{msg}",file = open(file_name, '+a'))
    if(SUCCESS_TEXT in msg):
        print(f"             [Switch - Storm Control] EMS Broadcast invalid Test Fail",file = open(file_name, '+a'))
        if_EMS_error = True
    e_swi.Switch_Storm_Control_Broadcast(driver,storm_control_num)
    e_swi.Switch_Setup_Storm_Control_Save(driver)    
    alert_accept(driver)

    # DLF: max+1 test     (%slot %port)
    time.sleep(3)
    e_swi.Switch_Storm_Control_Slot_Select(driver,slot)
    time.sleep(3)
    e_swi.Switch_Storm_Control_Port_Select(driver,port)
    time.sleep(3)
    e_swi.Switch_Storm_Control_DLF(driver,storm_control_num+1)
    time.sleep(3)
    e_swi.Switch_Setup_Storm_Control_Save(driver)
    msg = alert_accept_text(driver)
    print(f"             [Switch - Storm Control] EMS DLF invalid:{storm_control_num+1} msg:{msg}",file = open(file_name, '+a'))
    if(SUCCESS_TEXT in msg):
        print(f"             [Switch - Storm Control] EMS DLF invalid Test Fail",file = open(file_name, '+a'))
        if_EMS_error = True
    time.sleep(3)
    e_swi.Switch_Storm_Control_DLF(driver,storm_control_num)
    time.sleep(3)
    e_swi.Switch_Setup_Storm_Control_Save(driver)    
    alert_accept(driver)

    # Multicast: max+1 test     (%slot %port)
    time.sleep(3)
    e_swi.Switch_Storm_Control_Slot_Select(driver,slot)
    time.sleep(3)
    e_swi.Switch_Storm_Control_Port_Select(driver,port)
    time.sleep(3)
    e_swi.Switch_Storm_Control_Multicast(driver,storm_control_num+1)
    time.sleep(3)
    e_swi.Switch_Setup_Storm_Control_Save(driver)
    msg = alert_accept_text(driver)
    print(f"             [Switch - Storm Control] EMS Multicast invalid:{storm_control_num+1} msg:{msg}",file = open(file_name, '+a'))
    if(SUCCESS_TEXT in msg):
        print(f"             [Switch - Storm Control] EMS Multicast invalid Test Fail",file = open(file_name, '+a'))
        if_EMS_error = True
    time.sleep(3)
    e_swi.Switch_Storm_Control_Multicast(driver,storm_control_num)
    e_swi.Switch_Setup_Storm_Control_Save(driver)    
    alert_accept(driver)

    # EMS Result
    if(if_EMS_error == True):
        print(f"             [Switch - Storm Control] EMS web check fail",file = open(file_name, '+a'))
    else:
        print(f"             [Switch - Storm Control] EMS web check pass",file = open(file_name, '+a')) 

    # FW Result
    if(if_FW_error == True):
        print(f"             [Switch - Storm Control] FW web check fail",file = open(file_name, '+a'))
    else:
        print(f"             [Switch - Storm Control] FW web check pass",file = open(file_name, '+a')) 

    # Final Result    
    if((if_EMS_error == False) and (if_FW_error == False)):
        print(f"  [EMS1-{output_id}][Switch - Storm Control] Result Pass",file = open(file_name, '+a'))
        print(f"  [EMS1-6256][Switch - Storm Control - Setting - Apply] Result Pass",file = open(file_name, '+a'))
    else:
        print(f"  [EMS1-{output_id}][Switch - Storm Control] Result Fail",file = open(file_name, '+a'))
        print(f"  [EMS1-6256][Switch - Storm Control - Setting - Apply] Result Fail",file = open(file_name, '+a'))





