def Port_DHCP_2(driver,url,slot,port,output_id,username,password, ems_url, ems_password,file_name): # NXP support
    if_EMS_error = False
    if_FW_error = False

    driver.get(ems_url)
    time.sleep(5)
    mod.Login_EMS(driver,username,ems_password)
    time.sleep(5)
    EMS_Provision_Config_path(driver,url)
    time.sleep(2)    
    mod.Page_Switch(driver,"Port")   
    time.sleep(1)
    mod.SubPage_Switch(driver,"DHCP")
    time.sleep(3) 
    try:
        e_por.DHCP_Slot_Select(driver,slot)  
    except:
        print(f"             [Port - DHCP] EMS Slot {slot} Select Fail Test Fail",file = open(file_name, '+a'))
        if_EMS_error = True

    if if_EMS_error == False:
        e_por.DHCP_Port_Select(driver,port)     
        time.sleep(1)
        def test_enabled(title,element):
            if element.is_enabled():
                print(f"             [Port - DHCP] EMS {title} Element Enable Test Fail",file = open(file_name, '+a'))
            else:
                print(f"             [Port - DHCP] EMS {title} Element Disabled Test Pass",file = open(file_name, '+a'))
            return element.is_enabled()
        if_EMS_error = True if test_enabled("Option LDRA - Policy",driver.find_element(By.ID,"port_dhcp_optionldra_policy_select")) else if_EMS_error
        if_EMS_error = True if test_enabled("Option LDRA - Link Local",driver.find_element(By.ID,"port_dhcp_optionldra_linklocal_select")) else if_EMS_error
        if_EMS_error = True if test_enabled("Snooping Setting - Max Lease",driver.find_element(By.ID,"port_dhcp_max_lease")) else if_EMS_error
        if_EMS_error = True if test_enabled("Snooping Setting - Priority VLAN",driver.find_element(By.ID,"port_dhcp_priority_vlan")) else if_EMS_error
        if_EMS_error = True if test_enabled("Snooping Setting - IP MAC Binding",driver.find_element(By.ID,"port_dhcp_ipmacbinding1_select")) else if_EMS_error
        if_EMS_error = True if test_enabled("Snooping Setting - DHCPv4 Trust/Untrust",driver.find_element(By.ID,"port_dhcp_ipv4_select")) else if_EMS_error
        if_EMS_error = True if test_enabled("Snooping Setting - DHCPv6 Trust/Untrust",driver.find_element(By.ID,"port_dhcp_ipv6_select")) else if_EMS_error
        if_EMS_error = True if test_enabled("Static IP Filter Setting - Index",driver.find_element(By.ID,"port_dhcp_index_select")) else if_EMS_error
        if_EMS_error = True if test_enabled("Static IP Filter Setting - IP Address",driver.find_element(By.ID,"port_dhcp_ipaddress_text")) else if_EMS_error
        if_EMS_error = True if test_enabled("Static IP Filter Setting - IPv6 Prefix",driver.find_element(By.ID,"port_dhcp_ipv6prefix_text")) else if_EMS_error
        if_EMS_error = True if test_enabled("Static IP Filter Setting - IP MAC Binding",driver.find_element(By.ID,"port_dhcp_ipmacbinding2_select")) else if_EMS_error
        if_EMS_error = True if test_enabled("Static IP - 1",driver.find_element(By.ID,"port_dhcp_staticip1_text")) else if_EMS_error


        keys = ["Keep","Replace","Drop"]
        for key in keys:
            # --------------------- EMS web start ---------------------
            driver.get(ems_url)
            time.sleep(5)
            mod.Login_EMS(driver,username,ems_password)
            time.sleep(5)
            EMS_Provision_Config_path(driver,url)
            time.sleep(2)    
            mod.Page_Switch(driver,"Port")   
            time.sleep(1)
            mod.SubPage_Switch(driver,"DHCP")
            time.sleep(3) 
            e_por.DHCP_Slot_Select(driver,slot)  
            e_por.DHCP_Port_Select(driver,port)  
            e_por.DHCP_Option_82_Policy(driver,key)
            e_por.DHCP_Apply(driver)
            msg = alert_accept_text(driver)
            if(if_msg_not_success(msg)):
                print(f"             [Port - DHCP] EMS Option82 Policy: {key} msg:{msg} Apply Fail Test Fail",file = open(file_name, '+a'))
                if_EMS_error = True
            else:
                print(f"             [Port - DHCP] EMS Option82 Policy: {key} msg:{msg} Apply Pass Test Pass",file = open(file_name, '+a'))
            time.sleep(2)
            tmp = Select(driver.find_element(By.ID,'port_dhcp_option82_select')).first_selected_option.text #get_attribute("value")
            if(tmp != key): 
                print(f"             [Port - DHCP] EMS Option82 Policy {tmp}!={key} Test Fail",file = open(file_name, '+a'))
                if_EMS_error = True
            else:
                print(f"             [Port - DHCP] EMS Option82 Policy {key} Test Pass",file = open(file_name, '+a'))
            # --------------------- EMS web check end ------------------          
            # --------------------- FW web check start ----------------
            driver.get(url) 
            time.sleep(3)
            mod.Login(driver,username,password) 
            time.sleep(3)    
            mod.Switch_Default(driver)
            mod.Page_Switch(driver,"Port")
            time.sleep(1)            
            mod.SubPage_Switch(driver,"DHCP")         
            mod.Switch_Frame(driver)
            time.sleep(1) 
            por.DHCP_Slot_Select(driver,slot)
            time.sleep(1) 
            por.Port_Select(driver,port)
            time.sleep(1) 
            por.Load(driver)
            time.sleep(2) 
            tmp = Select(driver.find_element(By.NAME,'rpportdhcp_opt82Policy')).first_selected_option.text #get_attribute("value")
            if(tmp != key): 
                print(f"             [Port - DHCP] FW Option82 Policy {tmp}!={key} Test Fail",file = open(file_name, '+a'))
                if_FW_error = True
            else:
                print(f"             [Port - DHCP] FW Option82 Policy {key} Test Pass",file = open(file_name, '+a'))
            # --------------------- FW web check end ------------------          
    if(if_EMS_error == True):
        print(f"             [Port - DHCP] EMS web check fail",file = open(file_name, '+a'))
    else:
        print(f"             [Port - DHCP] EMS web check pass",file = open(file_name, '+a')) 
    # FW Result
    if(if_FW_error == True):
        print(f"             [Port - DHCP] FW web check fail",file = open(file_name, '+a'))
    else:
        print(f"             [Port - DHCP] FW web check pass",file = open(file_name, '+a')) 
    # Final Result          
    if((if_EMS_error == False) and (if_FW_error == False)):
        print(f"  [EMS1-6217][Port - DHCP - Apply] Result Pass",file = open(file_name, '+a'))
        print(f"  [EMS1-6218][Port - DHCP - Static IP Delete] Result Pass",file = open(file_name, '+a'))
    else:
        print(f"  [EMS1-6217][Port - DHCP - Apply] Result Fail",file = open(file_name, '+a'))
        print(f"  [EMS1-6218][Port - DHCP - Static IP Delete] Result Fail",file = open(file_name, '+a'))

