    print(f"             ({cardtype} {slot}-{port})",file = open(file_name, '+a'))

    print_list = []
    print_list.append('[EMS1-6243][VLAN - VLAN Untag and Copy-cpbit - Setting - Apply]')
    for i in print_list: print(f"  {i}",file = open(file_name, '+a'))

    match list_element[:1]:            
        case "1":
            if("1440" in cardtype):              
                output_id = '6243'      # GLC1440
            else:
                output_id = '6243'      # GLC1540
            
            VLAN_Untag_And_Copy_Cpbit_1(driver,url,slot,port,output_id,username,password, ems_url, ems_password,file_name)                  

        case "2":
            if("3416B" in cardtype):              
                output_id = '0000'      # OLC3416B        
