    print(f"  [EMS1-6245][VLAN - VLAN Tag Mode Setup - Clear] Result {tmp}",file = open(file_name, '+a'))
    # print(f"  [EMS1-6243][VLAN - VLAN Untag and Copy-cpbit - Apply] Result {tmp}",file = open(file_name, '+a'))
    print("======================================================================================",file = open(file_name, '+a'))



