def Create_ONT_VoIP_Sip_Profile(driver,username,ems_password,file_name, sip_profile_name = "sip_profile_SFU"):
    print(f"             Create EMS - Profile - ONT VoIP SIP Profile",file = open(file_name, '+a')) 
    e_pro.Profile_Path(driver,"ONT VoIP SIP Profile")       

    #  Start
    
    existing_index = e_pro.Profile_Name_Search(driver, sip_profile_name)
    if existing_index == -1 and If_Profile_Table_Full(driver,'0','ONT VoIP SIP Profile',file_name):
        return

    
    sip_profile_print_name = ["SFU","HGU"]
    if existing_index == -1:
        e_pro.Sip_Profile_New(driver)
        e_pro.Sip_Profile_New_Name(driver,sip_profile_name)
    else:
        with open(file_name, '+a') as report:
            print(f"             [Profile - ONT VoIP SIP Profile] {sip_profile_name} already exists; reuse and apply test settings", file=report)
    scroll_ele = driver.find_element('id','profile_content_div')
    e_pro.Sip_Profile_New_PSA(driver,"123456789012345678901234567890123456789012345678901234567890123")
    e_pro.Sip_Profile_New_OPA(driver,"123456789012345678901234567890123456789012345678901234567890123")
    e_pro.Sip_Profile_New_PD(driver,"1.1.1.254")
    e_pro.Sip_Profile_New_SD(driver,"2.2.2.254")
    e_pro.Sip_Profile_New_RET(driver,"25200")
    e_pro.Sip_Profile_New_RHST(driver,"360")
    Scroll(driver,scroll_ele)
    e_pro.Sip_Profile_New_HPU(driver,"123456789012345678901234567890123456789012345678901234567890123")
    e_pro.Sip_Profile_New_SR(driver,"123456789012345678901234567890123456789012345678901234567890123")
    e_pro.Sip_Profile_New_S(driver,"1234")
    # time.sleep(3)
    Scroll(driver,scroll_ele)
    e_pro.Sip_Profile_New_CI_cal_num(driver,True)
    e_pro.Sip_Profile_New_CI_cal_nam(driver,True)
    e_pro.Sip_Profile_New_CI_cid_bio(driver,True)
    e_pro.Sip_Profile_New_CI_cid_num(driver,True)
    e_pro.Sip_Profile_New_CI_cid_nam(driver,True)
    e_pro.Sip_Profile_New_CI_ACR(driver,True)
    e_pro.Sip_Profile_New_CW_cal_wai(driver,True)
    e_pro.Sip_Profile_New_CW_cid_ann(driver,True)
    e_pro.Sip_Profile_New_CPOT_3way(driver,True)
    e_pro.Sip_Profile_New_CPOT_cal_tra(driver,True)
    e_pro.Sip_Profile_New_CPOT_cal_hol(driver,True)
    e_pro.Sip_Profile_New_CPOT_cal_par(driver,True)
    e_pro.Sip_Profile_New_CPOT_not_dis(driver,True)
    e_pro.Sip_Profile_New_CPOT_flash(driver,True)
    try:
        e_pro.Sip_Profile_New_CPOT_origin(driver,True)                   # NO SEE ?????  need_add    
        e_pro.Sip_Profile_New_CPOT_6way(driver,True)                     # NO SEE ?????  need_add
    except:
        print(f"             [Profile - ONT VoIP SIP Profile] cannot interact with CPOT origin and CPOT 6way",file = open(file_name, '+a'))                
    e_pro.Sip_Profile_New_CP_spl_rin(driver,True)
    e_pro.Sip_Profile_New_CP_dia_ton(driver,True)
    e_pro.Sip_Profile_New_CP_vis_ind(driver,True)
    e_pro.Sip_Profile_New_CP_cal_for(driver,True)
    e_pro.Sip_Profile_New_DC_enable(driver,True)
    e_pro.Sip_Profile_New_DC_dia_opt(driver,True)
    Scroll(driver,scroll_ele)
    e_pro.Sip_Profile_New_DCU(driver,"123456789012345678901234567890123456789012345678901234567890123")
    e_pro.Sip_Profile_New_BLAU(driver,"123456789012345678901234567890123456789012345678901234567890123")
    e_pro.Sip_Profile_New_CFU(driver,"123456789012345678901234567890123456789012345678901234567890123")
    e_pro.Sip_Profile_New_Apply(driver)
    
    # check alert 
    msg = alert_accept_text(driver)
    if(if_msg_not_success(msg)):
        print(f"           [][Profile - ONT VoIP SIP Profile] msg:{msg} {sip_profile_name} {'Create' if existing_index == -1 else 'Reuse'} Fail",file = open(file_name, '+a'))        
        if_error = True
    else:
        print(f"           [][Profile - ONT VoIP SIP Profile] msg:{msg} {sip_profile_name} {'Create' if existing_index == -1 else 'Reuse'} Pass",file = open(file_name, '+a'))        

    print("",file = open(file_name, '+a'))

