def Create_ONT_VoIP_Common_Profile(driver,username,ems_password,file_name, voip_common_profile_name = "voip_common_SFU"):
    print(f"             Create EMS - Profile - ONT VoIP Common Profile",file = open(file_name, '+a')) 
    if_error = False

    # EMS - Profile - ONT VoIP Common Profile

    e_pro.Profile_Path(driver,"ONT VoIP Common Profile")


    # Start
    
    existing_index = e_pro.Profile_Name_Search(driver, voip_common_profile_name)
    if existing_index == -1 and If_Profile_Table_Full(driver,'EMS1-    ','ONT VoIP Common Profile',file_name):
        return
    
    
    voip_common_profile_print_name = "SFU"
    
    try:
        driver.maximize_window()
    except:
        pass
    if existing_index == -1:
        e_pro.Voip_Common_Profile_New(driver)
        e_pro.Voip_Common_Profile_New_Name(driver,voip_common_profile_name)
    else:
        with open(file_name, '+a') as report:
            print(f"             [Profile - ONT VoIP Common Profile] {voip_common_profile_name} already exists; reuse and apply test settings", file=report)
    e_pro.Voip_Common_Profile_New_min_Local_Port(driver,"65535")
    e_pro.Voip_Common_Profile_New_max_Local_Port(driver,"65535")
    e_pro.Voip_Common_Profile_New_dscp_mark(driver,"63")
    e_pro.Voip_Common_Profile_New_piggyback(driver,True)
    e_pro.Voip_Common_Profile_New_tone(driver,True)
    e_pro.Voip_Common_Profile_New_dtmf(driver,True)
    e_pro.Voip_Common_Profile_New_cas(driver,True)
    scroll_ele = driver.find_element('id','profile_content_div')
    Scroll(driver,scroll_ele)
    e_pro.Voip_Common_Profile_New_jitter_target(driver,"5000")
    e_pro.Voip_Common_Profile_New_max_jitter_buffer(driver,"500")             
    e_pro.Voip_Common_Profile_New_ptsn_protocol(driver,"999")           
    e_pro.Voip_Common_Profile_New_announce_type(driver,'Voi-ann')
    e_pro.Voip_Common_Profile_New_echo_cancel(driver,True)
    e_pro.Voip_Common_Profile_New_fax_mode(driver,'T38')
    e_pro.Voip_Common_Profile_New_1st_codec(driver,'G729')
    Scroll(driver,scroll_ele)
    e_pro.Voip_Common_Profile_New_2nd_codec(driver,'G729')
    e_pro.Voip_Common_Profile_New_3rd_codec(driver,'G729')
