def Create_ONT_VoIP_Dial_Plan_Profile(driver,username,ems_password,file_name, dial_plan_profile_name = "__dial_plan_SFU"):
    print(f"             Create EMS - Profile - ONT VoIP Dial Plan Profile",file = open(file_name, '+a')) 
    e_pro.Profile_Path(driver,"ONT VoIP Dial Plan Profile")

    # Start

    existing_index = e_pro.Profile_Name_Search(driver, dial_plan_profile_name)
    if existing_index == -1 and If_Profile_Table_Full(driver,'EMS1-    ','ONT VoIP Dial Plan Profile',file_name):
        return

    
    dial_plan_profile_print_name = ["SFU","HGU"]
   
    if existing_index == -1:
        e_pro.Dial_Plan_Profile_New(driver)
        e_pro.Dial_Plan_Profile_New_Name(driver,dial_plan_profile_name)
    else:
        with open(file_name, '+a') as report:
            print(f"             [Profile - ONT VoIP Dial Plan Profile] {dial_plan_profile_name} already exists; reuse and apply test settings", file=report)
    e_pro.Dial_Plan_Profile_New_MS(driver,"256")
    e_pro.Dial_Plan_Profile_New_CDT(driver,"8000")
    e_pro.Dial_Plan_Profile_New_PDT(driver,"32000")
    e_pro.Dial_Plan_Profile_New_format(driver,'H248') #* 4
    time.sleep(1)
    e_pro.Dial_Plan_Profile_New_CT(driver,"0123456789012345678901234567")### content-table token Test
    time.sleep(1)
    e_pro.Dial_Plan_Profile_New_Apply(driver)
    # check alert
    msg = alert_accept_text(driver)
    if(if_msg_not_success(msg)):
        print(f"           [][Profile - ONT VoIP Dial Plan Profile] msg:{msg} {'Create' if existing_index == -1 else 'Reuse'} Fail",file = open(file_name, '+a'))
        if_error = True
    else:
        print(f"           [][Profile - ONT VoIP Dial Plan Profile] msg:{msg} {'Create' if existing_index == -1 else 'Reuse'} Pass",file = open(file_name, '+a'))

    print("",file = open(file_name, '+a'))

