def Create_ONT_ACL_Profile(driver,ems_url,username,ems_password,file_name, prof_name = "!!!Auto_ACL_profile_xxxx"):
    print(f"             Create EMS - Profile - ONT ACL Profile",file = open(file_name, '+a')) 

    # --------------------- EMS web start ---------------------
    # EMS - Profile - ONT ACL Profile

    driver.get(ems_url)
    time.sleep(5)
    mod.Login_EMS(driver,username,ems_password)
    time.sleep(5)
    e_pro.Profile_Path(driver,"ONT ACL Profile")

    # Test Start

    

    existing = e_pro.Profile_Table_List_Edit_Name(driver, prof_name)
    if not existing and If_Profile_Table_Full(driver,'EMS1-0000','ONT ACL Profile',file_name):
        return
    
    if_error_new = False
    if_error = False
    
    time.sleep(3)
    if not existing:
        e_pro.ACL_Profile_New(driver)
        e_pro.ACL_Profile_New_Name(driver,prof_name)
    else:
        with open(file_name, '+a') as report:
            print(f"             [Profile - ONT ACL Profile] {prof_name} already exists; reuse and apply test settings", file=report)
    time.sleep(2)
    e_pro.ACL_Profile_New_Enable(driver,True)
    e_pro.ACL_Profile_New_Policy(driver,"Trust")
    e_pro.ACL_Profile_New_Interface(driver,"Both")
    e_pro.ACL_Profile_New_Count(driver,True)
    e_pro.ACL_Profile_New_Log(driver,True)
    e_pro.ACL_Profile_New_Protocol(driver,"255")
    e_pro.ACL_Profile_New_Src_Port(driver,"65535")
    e_pro.ACL_Profile_New_Dst_Port(driver,"65535")
    e_pro.ACL_Profile_New_Src_ip(driver,"10.10.10.1")
    # src mask
    try:
        e_pro.ACL_Profile_New_Src_mask(driver,"32")
    except:
        msg = alert_accept_text_no_block(driver)
        e_pro.ACL_Profile_New_Src_mask(driver,"32")
        print(f"             [Profile - ONT ACL Profile] (msg:{msg} need click ok to input src mask after input src ip)",file = open(file_name, '+a'))        
    # dst ip
    e_pro.ACL_Profile_New_Dst_ip(driver,"10.10.10.2")
    # dst mask
    try:
        e_pro.ACL_Profile_New_Dst_mask(driver,"32")    
    except:
        msg = alert_accept_text_no_block(driver)
        e_pro.ACL_Profile_New_Dst_mask(driver,"32")
        print(f"             [Profile - ONT ACL Profile] (msg:{msg} need click ok to input dst mask after input dst ip)",file = open(file_name, '+a'))        
    e_pro.ACL_Profile_New_Src_mac(driver,"10:10:10:10:10:01")
    e_pro.ACL_Profile_New_Dst_mac(driver,"10:10:10:10:10:02")
    e_pro.ACL_Profile_New_Apply(driver)

    # check alert (apply msg)
    msg = alert_accept_text(driver)
    if(if_msg_not_success(msg)):
        print(f"             [Profile - ONT ACL Profile] msg:{msg} {prof_name} Valid Input Apply Test Fail",file = open(file_name, '+a'))        
        if_error_new = True
    else:
        print(f"             [Profile - ONT ACL Profile] msg:{msg} {prof_name} Valid Input Apply Test Pass",file = open(file_name, '+a'))        

    if(if_error_new == False):
        print(f"           [][Profile - ONT ACL Profile] {'Reuse' if existing else 'Create'} Pass",file = open(file_name, '+a'))
    else:
        print(f"           [][Profile - ONT ACL Profile] {'Reuse' if existing else 'Create'} Fail",file = open(file_name, '+a'))

    print("",file = open(file_name, '+a'))

