def IGMP_Group_Privilege_Profile(driver,ems_url,username,ems_password,file_name):

    print(f"EMS - Profile - IGMP Group Privilege Profile Test\n",file = open(file_name, '+a')) 

    # --------------------- EMS web start ---------------------
    # EMS - Profile - IGMP Group Privilege Profile

    driver.get(ems_url)
    time.sleep(5)
    mod.Login_EMS(driver,username,ems_password)
    time.sleep(5)

    # Test Start ...
                
    prof_name = "!!!AutoTest_DoNotDelete_xxxxxxx"  # "1234567890123456789012345678001"


