def Create_Weight_Profile(driver,ems_url,username,ems_password,file_name,prof_name = "!!!AutoTest_DoNotDelete_xxxxxxx"):

    print(f"             Create EMS - Profile - Weight Profile",file = open(file_name, '+a')) 

    # --------------------- EMS web start ---------------------
    # EMS - Profile - Weight Profile

    driver.get(ems_url)
    time.sleep(5)
    mod.Login_EMS(driver,username,ems_password)
    time.sleep(5)
    e_pro.Profile_Path(driver,"Weight Profile")

    # Test Start ...
     # '1234567890123456789012345678000'
    Delete_Profile_1(driver,prof_name,'Weight Profile',file_name)
    if(If_Profile_Table_Full(driver,'EMS1-0000','Weight Profile',file_name) == True):
        return    

    e_pro.New_Profile(driver)
    e_pro.Weight_Profile_Name(driver,prof_name)    

    # NEW ---------------------------------------------------------------------
    print(f"             [Profile - Weight Profile] (New)",file = open(file_name, '+a'))
    if_error = False
    
    # Valid Input            
    for index in range(8):
        e_pro.Weight_Weight_Queue(driver,index,"50")
    e_pro.Weight_Apply(driver)

    # check  alert  
    msg = alert_accept_text(driver)
    if(if_msg_not_success(msg)):
        print(f"             [Profile - Weight Profile] msg:{msg} Valid Value Alert Test Fail",file = open(file_name, '+a'))
        if_error = True
    else:
        print(f"             [Profile - Weight Profile] msg:{msg} Valid Value Alert Test Pass",file = open(file_name, '+a'))
    if(if_error == False):
        print(f"           [][Profile - Weight Profile] Create Pass\n",file = open(file_name, '+a'))
    else:
        print(f"           [][Profile - Weight Profile] Create Fail\n",file = open(file_name, '+a'))
    
    # NEW END ------------------------------------------------------------------


