@retry()
def Create_zzz_profile_for_Sort_test(driver,ems_url,username,ems_password,file_name):
    print("======================================================================================",file = open(file_name, '+a'))
    profile_name = 'zzzzzzzzzzzzzzzzzzzzzzzzzzzzzz'    # 31
    profile_name_for_acl =  'zzzzzzzzzzzzzzzzzzzzzzzz'  # 24
    profile_name_for_voip = 'zzzzzzzzzzzzzzz'          # 15
    def my_create_zzz_profile(driver,profile_test_name,profile_n):    
        # print(f'Now in {profile_test_name} \n Processing...')
        driver.find_element(By.LINK_TEXT,"Profile").click()
        time.sleep(1)
        e_pro.Profile_Select(driver,profile_test_name)
        time.sleep(1)
        
        e_pro.New_Profile(driver)
        e_pro.Profile_Name(driver,f'{profile_n}')
        e_pro.Save(driver)
        try:
            msg = alert_accept_text_no_block(driver)
            if('uccess' not in msg):
                print(f'msg:{msg} (create zzz {profile_test_name} {profile_n})',file = open(file_name, '+a'))
        except:
            print(f'{profile_n} may save fail (create zzz {profile_test_name} {profile_n})',file = open(file_name, '+a'))
            pass
        # print('finished.')

    # Create zzz profile
    Create_ONT_Service_Profile(driver,ems_url,username,ems_password,file_name,profile_name) # 
    Create_ONT_QoS_Bandwidth_Profile(driver,ems_url,username,ems_password,file_name,profile_name) #
    # Create_ONT_Multicast_Profile(driver,username,ems_password, ems_url, ems_password,file_name,profile_name) #
    Create_ONT_UNI_Profile(driver,ems_url,username,ems_password,file_name,profile_name) #
    # Create_ONT_ONT_Profile(driver,username,ems_password,file_name,profile_name) # 
    Create_ONT_Security_Profile(driver,ems_url,username,ems_password,file_name,profile_name) #  
    Create_ONT_ACL_Profile(driver,ems_url,username,ems_password,file_name,profile_name_for_acl) # 
    Create_ONT_Alarm_Profile(driver,ems_url,username,ems_password,file_name,profile_name)#

    # Create_ONT_VoIP_Sip_Profile(driver,username,ems_password,file_name,profile_name_for_voip)  # 
    # Create_ONT_VoIP_Common_Profile(driver,username,ems_password,file_name,profile_name_for_voip)  #
    # Create_ONT_VoIP_Dial_Plan_Profile(driver,username,ems_password,file_name,profile_name_for_voip) #
    Create_IGMP_Group_Privilege_Profile(driver,ems_url,username,ems_password,file_name,profile_name)

    my_create_zzz_profile(driver,"ONT VoIP SIP Profile",profile_name_for_voip)#
    my_create_zzz_profile(driver,"ONT VoIP Common Profile",profile_name_for_voip)#
    my_create_zzz_profile(driver,"ONT VoIP Dial Plan Profile",profile_name_for_voip)#
    my_create_zzz_profile(driver,"ONT Multicast Profile",profile_name)#
    my_create_zzz_profile(driver,"ONT ONT Profile",profile_name)#
    my_create_zzz_profile(driver,"Rate Limit Profile",profile_name)#
    my_create_zzz_profile(driver,"Shaping Profile",profile_name) #
