    my_create_zzz_profile(driver,"ONT Template","ＺＺＺＺＺＺＺＺＺＺＺＺＺＺＺＺＺＺＺＺＺＺＺＺＺＺＺＺＺＺＺ")#
    print(f"             Create zzz profiles done.",file = open(file_name, '+a'))
