def Profile_Sort_Test(driver,text1,text2,file_name,profile_name='zzzzzzzzzzzzzzzzzzzzzzzzzzzzzz'):
    '''
        text1: id
        text2: profile type
    '''

    output_path = f'Profile - {text2} - Sort'
    # text = f"  [EMS1-0000][Profile - ONT Alarm Profile - Sort] Result "
    text = f"  {text1}[{output_path}] Result "
    print(f"",file = open(file_name, '+a'))
    # print(f"             [{output_path}] (Sort)",file = open(file_name, '+a'))

    if_error = False

    if(e_pro.Profile_Table_List_Edit_Name(driver,profile_name) == False):
        print(f"             [{output_path}] not found '{profile_name}' in the first or last page",file = open(file_name, '+a'))
        if_error = True
    else:

        # Test Sort 
        sort_status = driver.find_element(By.XPATH,'//*[@id="profile_table_head"]/thead/tr/th[4]/img').get_attribute("date-type")
        if(sort_status != 'hide'):
            e_pro.Profile_Name_Sort_Click(driver)
        # check the first profile's name
        the_first_profile_name = driver.find_element(By.NAME,"row0").get_attribute("index_2")
        if(the_first_profile_name != profile_name):
            if_error = True
    
    print(text,end='',file = open(file_name, '+a'))
    print('Fail\n',file = open(file_name, '+a')) if if_error else print('Pass\n',file = open(file_name, '+a'))


    
