def msc_test(driver,url,MSC_card,MSC_slot,username,password, ems_url, ems_password,file_name):
    print(f"EMS - ACL - DHCP Remote Backup Test\n",file = open(file_name, '+a')) 
    if_EMS_error = False
    if_FW_error = False

    # --------------------- EMS web start ---------------------
    # EMS - ACL - DHCP Remote Backup
    
    # EMS website > login
    driver.get(ems_url)
    time.sleep(5)
    mod.Login_EMS(driver,username,ems_password)
    time.sleep(5)
    
    EMS_Provision_Config_path(driver,url)
    time.sleep(2)    
    driver.find_element(By.LINK_TEXT,"ACL").click()          
    time.sleep(1)
    driver.find_element(By.LINK_TEXT,"DHCP Remote Backup").click()
    time.sleep(3)
    
    # ...
    print(f"             [ACL - DHCP Remote Backup] No Action?",file = open(file_name, '+a'))


    # --------------------- EMS web end -----------------------

    # EMS Result
    if(if_EMS_error == True):
        print(f"             [ACL - DHCP Remote Backup] EMS web check fail",file = open(file_name, '+a'))
    else:
        print(f"             [ACL - DHCP Remote Backup] EMS web check pass",file = open(file_name, '+a')) 

    # FW Result
    if(if_FW_error == True):
        print(f"             [ACL - DHCP Remote Backup] FW web check fail",file = open(file_name, '+a'))
    else:
        print(f"             [ACL - DHCP Remote Backup] FW web check pass",file = open(file_name, '+a')) 

    # Final Result
    if("XB" in MSC_card):
        output_id = "000?"
    elif("XA" in MSC_card):
        output_id = "000?"
    elif("QA" in MSC_card):
        output_id = "000?"
    else:
        output_id = "0000"         
    if((if_EMS_error == False) and (if_FW_error ==False)):
        print(f"  [EMS1-{output_id}][ACL - DHCP Remote Backup] Result Pass",file = open(file_name, '+a'))
        print(f"  [EMS1-6105][ACL - DHCP Remote Backup Apply] Result Pass",file = open(file_name, '+a'))
        print(f"  [EMS1-6106][ACL - DHCP Remote Backup Manual download] Result Pass",file = open(file_name, '+a'))
    else:
        print(f"  [EMS1-{output_id}][ACL - DHCP Remote Backup] Result Fail",file = open(file_name, '+a'))
        print(f"  [EMS1-6105][ACL - DHCP Remote Backup Apply] Result Fail",file = open(file_name, '+a'))
