    # test_name_column = lines[4].split('"')[1]             ### variable test name column
    # html_file_num = lines[6].split('"')[1] 

    output_column_list = output_column.split(',')
    file_name = 'Output1213.txt'
    output_txt = open(file_name,"w+")


    # Online google sheet
    scopes = ["https://spreadsheets.google.com/feeds"]
    credentials = ServiceAccountCredentials.from_json_keyfile_name("local-cedar-394416-44b2e200a93a.json", scopes)
    client = gspread.authorize(credentials)   

    wb = client.open_by_key(excel_online_link) 
    if_exist = True
    try:
        s1 = wb.worksheet(sheet_name)
    except:
        Print(f"'{sheet_name}' worksheet Not Found ...",file_name)
        if_exist = False


    # Process
    if(if_exist == True):
        ###
        #  Output 
        Print('Processing...',file_name)
        for model in ont_list.keys():
            # position = str(s1.find(f'{model}',in_column = strtonum(test_name_column)))       ### test name column
            position = str(s1.find(f'{model}',in_row=1))
            if(position == 'None'):
                Print(f'not found "{model}" ({ont_list[model]})',file_name)
            else:
                R = position.split(" ")[1].split("R")[1].split("C")[0]
                C = position.split(" ")[1].split("C")[1]
                s1.batch_update([{ 'range': f'{C}{R}',  'values': [[ont_list[model]]],}])   # output pass/fail num
        Print('done\n',file_name)
        ###

        # for index in range(int(html_file_num)):

        #     Print('Processing...',file_name)

        #     file_path = html_file_path + lines[index + 7].split(',')[0] + '.html'
        #     Print(f'File path No.{index + 1}: {file_path}',file_name)
