def UserContinue(driver,username,password):

    driver.switch_to.default_content()
    try:
        driver.find_element('id',"userContinue").click()
    except:
        # if(driver.find_elements('class name', "ui-dialog.ui-widget.ui-widget-content.ui-corner-all.ui-front.ui-draggable").__len__()>0):
        # driver.find_element('class name', "ui-dialog.ui-widget.ui-widget-content.ui-corner-all.ui-front.ui-draggable")
        try:
            driver.find_element('id',"lg_user").send_keys(username)
            driver.find_element('id',"lg_pass").send_keys(password)
            driver.find_element('id',"userLogin").click()
        except:
            pass
    try:
        driver.switch_to.frame(0)
    except:
        pass




