        mod.Login_EMS(driver,module.variable_module.ems_username,module.variable_module.ems_password)
        time.sleep(5)    
        EMS_Provision_Config_path(driver,url)

        

        with open('ENV\\not_support.json', 'r') as file:
            data = json.load(file)
        print("======================================================================================",file = open(file_name, '+a'))
        print(f"             EMS MSC slot {MSC_slot} No support Test Start",file = open(file_name, '+a'))
        print("======================================================================================",file = open(file_name, '+a'))
